def hash_pw(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def now():
    return datetime.now().strftime("%d/%m/%Y %H:%M:%S")


def make_code():
    return f"{secrets.randbelow(1000000):06d}"


def make_parent_temp():
    return "PH" + str(secrets.randbelow(900000) + 100000)


def make_teacher_code():
    return "GV" + f"{secrets.randbelow(1000000):06d}"


def get_teacher_code():
    con = connect()
    try:
        row = con.execute("SELECT verification_code FROM teacher WHERE id=1").fetchone()
        if row and row["verification_code"]:
            return row["verification_code"]
        code = make_teacher_code()
        con.execute("UPDATE teacher SET verification_code=? WHERE id=1", (code,))
        con.commit()
        return code
    finally:
        con.close()


def connect():
    con = sqlite3.connect(DB_FILE)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys = ON")
    return con


def init_db():
    con = connect()
    cur = con.cursor()

    cur.execute("""
        CREATE TABLE IF NOT EXISTS teacher (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            verification_code TEXT,
            display_name TEXT DEFAULT '',
            avatar_path TEXT DEFAULT ''
        )
    """)
    try:
        cur.execute("ALTER TABLE teacher ADD COLUMN verification_code TEXT")
    except sqlite3.OperationalError:
        pass

    for col, typ in [("display_name", "TEXT DEFAULT ''"), ("avatar_path", "TEXT DEFAULT ''")]:
        try:
            cur.execute(f"ALTER TABLE teacher ADD COLUMN {col} {typ}")
        except sqlite3.OperationalError:
            pass

    cur.execute("""
        CREATE TABLE IF NOT EXISTS classes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_name TEXT UNIQUE NOT NULL,
            homeroom_teacher TEXT NOT NULL,
            group_name TEXT DEFAULT '',
            group_avatar_path TEXT DEFAULT ''
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS students (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            class_name TEXT NOT NULL,
            team TEXT NOT NULL,
            homeroom_teacher TEXT NOT NULL,
            parent_name TEXT NOT NULL,
            parent_email TEXT NOT NULL,
            group_name TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'pending',
            access_code TEXT,
            created_at TEXT NOT NULL,
            approved_at TEXT,
            verified_at TEXT
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS parents (
            student_id INTEGER PRIMARY KEY,
            email TEXT NOT NULL,
            password_hash TEXT NOT NULL,
            must_change INTEGER NOT NULL DEFAULT 1,
            verified INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS parent_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_name TEXT NOT NULL,
            parent_email TEXT NOT NULL,
            student_name TEXT NOT NULL,
            class_name TEXT NOT NULL,
            team TEXT NOT NULL,
            homeroom_teacher TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            created_at TEXT NOT NULL,
            approved_at TEXT
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS scores (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id INTEGER NOT NULL,
            criterion TEXT NOT NULL,
            points INTEGER NOT NULL,
            note TEXT,
            created_at TEXT NOT NULL,
            FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS class_officers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id INTEGER UNIQUE NOT NULL,
            role TEXT NOT NULL,
            scope TEXT NOT NULL DEFAULT 'Không làm gì cả',
            FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS diagram_settings (
            id INTEGER PRIMARY KEY,
            layout TEXT NOT NULL DEFAULT 'grid'
        )
    """)
    cur.execute("INSERT OR IGNORE INTO diagram_settings(id,layout) VALUES(1,'grid')")
    try:
        cur.execute("ALTER TABLE classes ADD COLUMN group_name TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute("ALTER TABLE class_officers ADD COLUMN scope TEXT DEFAULT 'Không làm gì cả'")
    except sqlite3.OperationalError:
        pass

    cur.execute("""
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id INTEGER NOT NULL,
            task_date TEXT NOT NULL,
            task TEXT NOT NULL,
            status TEXT NOT NULL,
            points INTEGER NOT NULL DEFAULT 0,
            note TEXT,
            FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE
        )
    """)

    try:
        cur.execute("ALTER TABLE students ADD COLUMN officer_role TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    for col, typ in [
        ("student_username", "TEXT DEFAULT ''"),
        ("student_password_hash", "TEXT DEFAULT ''"),
        ("student_password_display", "TEXT DEFAULT ''"),
        ("officer_scope", "TEXT DEFAULT 'Không làm gì cả'"),
        ("transfer_notice", "TEXT DEFAULT ''"),
        ("group_name", "TEXT DEFAULT ''"),
    ]:
        try:
            cur.execute(f"ALTER TABLE students ADD COLUMN {col} {typ}")
        except sqlite3.OperationalError:
            pass
    try:
        cur.execute("ALTER TABLE parents ADD COLUMN password_display TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute("ALTER TABLE parents ADD COLUMN username TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute("ALTER TABLE parent_requests ADD COLUMN parent_username TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute("ALTER TABLE parent_requests ADD COLUMN parent_password_hash TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute("ALTER TABLE parent_requests ADD COLUMN parent_password_display TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    legacy_students=cur.execute("SELECT id,student_username,student_password_hash,student_password_display FROM students").fetchall()
    for st in legacy_students:
        u=st["student_username"] or f"hs{st['id']:04d}"; pw=st["student_password_display"] or secrets.token_hex(3)
        if not st["student_password_hash"] or not st["student_password_display"] or not st["student_username"]:
            cur.execute("UPDATE students SET student_username=?,student_password_hash=?,student_password_display=? WHERE id=?",(u,hash_pw(pw),pw,st["id"]))

    # V8: lưu các kỳ tổng kết do giáo viên tạo. Dữ liệu tổng kết được lấy trực tiếp
    # từ điểm, nhiệm vụ và nhận xét trong khoảng thời gian đã chọn.
    cur.execute("""
        CREATE TABLE IF NOT EXISTS summaries (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id INTEGER NOT NULL,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            learning_situation TEXT DEFAULT '',
            commendation TEXT DEFAULT '',
            criticism TEXT DEFAULT '',
            conclusion TEXT DEFAULT '',
            created_at TEXT NOT NULL,
            FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE
        )
    """)

    # V9: CHAT - nhóm lớp, chat riêng giáo viên/học sinh/phụ huynh, tim, tệp,
    # tin nhắn nhanh và nhắc hẹn. Dữ liệu dùng chung với SQLite của hệ thống.
    cur.execute("""
        CREATE TABLE IF NOT EXISTS chat_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_type TEXT NOT NULL DEFAULT 'private',
            class_name TEXT DEFAULT '',
            peer_student_id INTEGER,
            peer_type TEXT DEFAULT '',
            sender_type TEXT NOT NULL,
            sender_student_id INTEGER,
            sender_name TEXT NOT NULL,
            message TEXT DEFAULT '',
            attachment_path TEXT DEFAULT '',
            created_at TEXT NOT NULL,
            FOREIGN KEY(peer_student_id) REFERENCES students(id) ON DELETE CASCADE,
            FOREIGN KEY(sender_student_id) REFERENCES students(id) ON DELETE SET NULL
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS chat_likes (
            message_id INTEGER NOT NULL,
            liker_key TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY(message_id, liker_key),
            FOREIGN KEY(message_id) REFERENCES chat_messages(id) ON DELETE CASCADE
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS chat_quick_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            text TEXT UNIQUE NOT NULL
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS chat_reminders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            remind_at TEXT NOT NULL,
            note TEXT DEFAULT '',
            created_at TEXT NOT NULL,
            done INTEGER NOT NULL DEFAULT 0
        )
    """)
    for q in [
        'Em nhớ hoàn thành nhiệm vụ đúng hạn nhé.',
        'Cô/thầy đã xem và ghi nhận.',
        'Chúc em học tập tốt và hoàn thành nhiệm vụ.',
        'Phụ huynh vui lòng xem thông báo của giáo viên.',
        'Nhắc cả lớp chuẩn bị nhiệm vụ theo yêu cầu.'
    ]:
        cur.execute('INSERT OR IGNORE INTO chat_quick_messages(text) VALUES(?)', (q,))

    cur.execute("""
        INSERT OR IGNORE INTO teacher(id, username, password_hash)
        VALUES (1, ?, ?)
    """, (TEACHER_USER, hash_pw(DEFAULT_PASSWORD)))
    row_teacher=cur.execute("SELECT * FROM teacher WHERE id=1").fetchone()
    if not row_teacher["verification_code"]:
        cur.execute("UPDATE teacher SET verification_code=? WHERE id=1", (make_teacher_code(),))
    if not (row_teacher["display_name"] or '').strip():
        cur.execute("UPDATE teacher SET display_name=? WHERE id=1", (TEACHER_NAME,))
    # V15/V16: thêm ảnh đại diện nhóm lớp.
    try:
        cur.execute("ALTER TABLE classes ADD COLUMN group_avatar_path TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass
    # Gán tên nhóm mặc định cho các lớp cũ.
    cur.execute("UPDATE classes SET group_name=? WHERE COALESCE(group_name,'')=''", ("Nhóm lớp",))

    # V12.1: tên GVCN chính thức của hệ thống.
    # Chỉ đổi dữ liệu cũ đang dùng tên mặc định/sai; không đụng tới tên giáo viên khác.
    for table in ("classes", "students", "parent_requests"):
        try:
            cur.execute(
                f"UPDATE {table} SET homeroom_teacher=? "
                "WHERE homeroom_teacher=?",
                (TEACHER_NAME, "Nguyễn Thị Hương")
            )
        except sqlite3.OperationalError:
            pass

    con.commit()
    con.close()


