    def _png(self, data, width=None, height=None):
        img = tk.PhotoImage(data=data)
        if width and img.width() > width:
            factor = max(1, (img.width() + width - 1) // width)
            img = img.subsample(factor, factor)
        if height and img.height() > height:
            factor = max(1, (img.height() + height - 1) // height)
            img = img.subsample(factor, factor)
        return img

    def hero_image(self, parent, max_cols=2, height=310):
        try:
            img = self._png(HERO_B64, width=520)
            label = tk.Label(parent, image=img, bg='white', bd=0, highlightthickness=0)
            label.image = img
            label.pack(fill='both', expand=True, padx=8, pady=8)
            return label
        except Exception:
            label = tk.Label(parent, text='🌈\nQUẢN LÝ HỌC SINH', bg='#dceeff',
                             fg=COLORS['navy'], font=('Arial', 26, 'bold'))
            label.pack(fill='both', expand=True, padx=8, pady=8)
            return label

    def avatar_image(self, parent, size=52, seed='teacher'):
        """Tạo avatar tròn, không chữ. Mỗi người có mẫu màu khác nhau theo seed."""
        if PIL_OK:
            try:
                import hashlib as _hashlib
                d = _hashlib.sha256(str(seed).encode('utf-8')).digest()
                c1 = (70 + d[0] % 150, 90 + d[1] % 130, 120 + d[2] % 120, 255)
                c2 = (80 + d[3] % 150, 80 + d[4] % 140, 100 + d[5] % 130, 255)
                img = Image.new('RGBA', (size, size), (0, 0, 0, 0))
                draw = ImageDraw.Draw(img)
                draw.ellipse((0, 0, size-1, size-1), fill=c1)
                r = max(6, size // 3)
                x = d[6] % max(1, size-r)
                y = d[7] % max(1, size-r)
                draw.ellipse((x, y, min(size-1, x+r), min(size-1, y+r)), fill=c2)
                r2 = max(4, size // 5)
                x2 = d[8] % max(1, size-r2)
                y2 = d[9] % max(1, size-r2)
                draw.ellipse((x2, y2, min(size-1, x2+r2), min(size-1, y2+r2)), fill=(255,255,255,70))
                mask = Image.new('L', (size, size), 0)
                ImageDraw.Draw(mask).ellipse((0, 0, size-1, size-1), fill=255)
                img.putalpha(mask)
                photo = ImageTk.PhotoImage(img)
                lab = tk.Label(parent, image=photo, bg=parent.cget('bg'), bd=0, highlightthickness=0)
                lab.image = photo
                return lab
            except Exception:
                pass
        # Fallback không chữ: vòng tròn trên Canvas.
        cv = tk.Canvas(parent, width=size, height=size, bg=parent.cget('bg'),
                       bd=0, highlightthickness=0)
        cv.create_oval(2, 2, size-2, size-2, fill='#6b8cff', outline='')
        return cv

    def logo_image(self, parent, size=46):
        try:
            img = self._png(LOGO_B64, width=size, height=size)
            lab = tk.Label(parent, image=img, bg='white', bd=0)
            lab.image = img
            return lab
        except Exception:
            return tk.Label(parent, text='🎓', bg='white', font=('Arial', 24))

    def pill(self, parent, text, color, width=13):
        return tk.Label(parent, text=text, bg=color, fg="white",
                        font=("Arial", 9, "bold"), padx=10, pady=4)

    def stat_card(self, parent, title, value, subtitle="", color=None, icon=""):
        color = color or COLORS["blue"]
        f = tk.Frame(parent, bg="white", bd=1, relief="solid",
                     highlightbackground=COLORS["line"], highlightthickness=1)
        tk.Label(f, text=icon, bg="white", fg=color,
                 font=("Segoe UI Emoji", 18)).pack(pady=(8, 0))
        tk.Label(f, text=str(value), bg="white", fg=COLORS["navy"],
                 font=("Arial", 20, "bold")).pack()
        tk.Label(f, text=title, bg="white", fg=COLORS["dark"],
                 font=("Arial", 10, "bold")).pack()
        if subtitle:
            tk.Label(f, text=subtitle, bg="white", fg=COLORS["gray"],
                     font=("Arial", 8)).pack(pady=(0, 8))
        return f

    def sidebar_button(self, parent, text, command, color="#eaf0ff"):
        b = tk.Button(parent, text=text, command=command, anchor="w",
                      bg=color, fg=COLORS["navy"], activebackground="#dce7ff",
                      activeforeground=COLORS["navy"], relief="flat",
                      font=("Arial", 9, "bold"), bd=0, padx=12, pady=8,
                      cursor="hand2")
        return b

    def clear(self):
        for widget in self.winfo_children():
            widget.destroy()

    def header(self, title, subtitle=""):
        tk.Label(
            self, text=title, bg=COLORS["bg"], fg="#3155a6",
            font=("Arial", 24, "bold")
        ).pack(pady=(18, 3))
        if subtitle:
            tk.Label(
                self, text=subtitle, bg=COLORS["bg"], fg=COLORS["gray"],
                font=("Arial", 10)
            ).pack(pady=(0, 12))

    def button(self, parent, text, command, width=18, color=None):
        return tk.Button(
            parent, text=text, command=command, width=width,
            bg=color or COLORS["blue"], fg="white",
            activebackground="#3155a6", activeforeground="white",
            font=("Arial", 10, "bold"), relief="flat",
            padx=8, pady=8, cursor="hand2"
        )

    def tree(self, columns, headings, widths=None):
        frame = tk.Frame(self, bg=COLORS["bg"])
        frame.pack(fill="both", expand=True, padx=18, pady=8)
        tr = ttk.Treeview(frame, columns=columns, show="headings")
        if widths is None:
            widths = [max(90, 1050 // len(columns))] * len(columns)
        for col, heading, width in zip(columns, headings, widths):
            tr.heading(col, text=heading)
            tr.column(col, width=width, minwidth=60)
        y = ttk.Scrollbar(frame, orient="vertical", command=tr.yview)
        tr.configure(yscrollcommand=y.set)
        tr.pack(side="left", fill="both", expand=True)
        y.pack(side="right", fill="y")
        return tr

