    def parent_register(self):
        self.clear()
        self.header(
            "📝 ĐĂNG KÝ PHỤ HUYNH",
            "Phụ huynh tự tạo tên đăng nhập + mật khẩu → giáo viên xác nhận"
        )
        card=tk.Frame(self,bg="white",bd=1,relief="solid")
        card.pack(pady=10,ipadx=30,ipady=20)

        labels=[
            "Họ tên phụ huynh",
            "Tên đăng nhập phụ huynh",
            "Mật khẩu phụ huynh",
            "Email phụ huynh",
            "Họ tên con",
            "Lớp của con",
            "Tổ của con",
            "Giáo viên chủ nhiệm"
        ]
        entries=[]
        for i,l in enumerate(labels):
            tk.Label(card,text=l+":",bg="white",font=("Arial",10,"bold")).grid(
                row=i,column=0,sticky="e",padx=10,pady=7
            )
            e=tk.Entry(card,width=42,show="*" if "Mật khẩu" in l else "")
            e.grid(row=i,column=1,padx=10,pady=7)
            entries.append(e)
        entries[-1].insert(0,TEACHER_NAME)

        def submit():
            v=[e.get().strip() for e in entries]
            if not all(v) or "@" not in v[3]:
                messagebox.showwarning(
                    "Thiếu thông tin",
                    "Hãy nhập đủ họ tên, tên đăng nhập, mật khẩu, email, thông tin con và giáo viên."
                )
                return
            if len(v[2]) < 6:
                messagebox.showwarning("Mật khẩu","Mật khẩu phụ huynh phải có ít nhất 6 ký tự.")
                return

            con=connect()
            try:
                dup=con.execute(
                    "SELECT 1 FROM parents WHERE lower(username)=lower(?) LIMIT 1",
                    (v[1],)
                ).fetchone()
                if dup:
                    messagebox.showwarning("Tên đăng nhập","Tên đăng nhập phụ huynh đã tồn tại.")
                    return

                con.execute("""
                    INSERT INTO parent_requests(
                        parent_name,parent_email,parent_username,
                        parent_password_hash,parent_password_display,
                        student_name,class_name,team,homeroom_teacher,status,created_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,'pending',?)
                """,(
                    v[0],v[3],v[1],hash_pw(v[2]),v[2],
                    v[4],v[5],v[6],v[7],now()
                ))
                con.commit()
            except Exception as e:
                con.rollback()
                messagebox.showerror("Đăng ký thất bại",f"Không thể gửi yêu cầu phụ huynh.\n\n{e}")
                return
            finally:
                con.close()

            messagebox.showinfo(
                "Đã gửi",
                "Yêu cầu phụ huynh đã gửi giáo viên.\n"
                "Tên đăng nhập và mật khẩu bạn tự tạo sẽ được giữ nguyên khi được xác nhận."
            )
            self.show_login()

        self.button(card,"📨 GỬI YÊU CẦU CHO GIÁO VIÊN",submit,30,COLORS["pink"]).grid(
            row=len(labels),column=0,columnspan=2,pady=14
        )
        self.button(self,"Quay lại",self.parent_role,15,"#7f8c8d").pack()

