    def complete_first_login_profile(self, student_row, after_save=None):
        """Bắt buộc cập nhật Tổ, Tên nhóm và Gmail phụ huynh khi tài khoản nhập từ Excel còn thiếu dữ liệu."""
        sid=int(student_row.get("id", student_row.get("student_id")))
        con=connect(); live=con.execute("SELECT * FROM students WHERE id=?",(sid,)).fetchone(); con.close()
        if not live:
            return
        missing = (not (live["team"] or "").strip()) or (not (live["parent_email"] or "").strip())
        if not missing and (live["group_name"] or "").strip():
            if after_save: after_save()
            return

        win=tk.Toplevel(self); win.title("🔐 CẬP NHẬT THÔNG TIN LẦN ĐẦU"); win.geometry("620x450"); win.configure(bg="white")
        win.transient(self); win.grab_set()
        tk.Label(win,text="🔐 CẬP NHẬT THÔNG TIN LẦN ĐẦU",bg="white",fg=COLORS["navy"],font=("Arial",18,"bold")).pack(pady=(20,6))
        tk.Label(win,text="Tài khoản được cấp từ danh sách Excel còn thiếu thông tin.\nVui lòng nhập đủ để vào hệ thống.",bg="white",fg=COLORS["gray"],justify="center").pack(pady=(0,14))
        card=tk.Frame(win,bg="white"); card.pack(padx=30,pady=4)
        team=tk.StringVar(value=(live["team"] or "").strip())
        group=tk.StringVar(value=(live["group_name"] or "").strip())
        email=tk.StringVar(value=(live["parent_email"] or "").strip())
        fields=[("Tổ",team),("Tên nhóm",group),("Gmail phụ huynh",email)]
        for i,(lab,var) in enumerate(fields):
            tk.Label(card,text=lab+":",bg="white",font=("Arial",10,"bold"),width=20,anchor="e").grid(row=i,column=0,padx=8,pady=10)
            tk.Entry(card,textvariable=var,width=40).grid(row=i,column=1,padx=8,pady=10)
        info=tk.Label(win,text="",bg="#fff8e8",fg="#7a4b00",font=("Arial",9),wraplength=520,justify="center")
        info.pack(fill="x",padx=30,pady=8,ipady=7)
        def save():
            t=team.get().strip(); g=group.get().strip(); em=email.get().strip()
            if not t or not g or not em:
                info.config(text="Vui lòng nhập đủ Tổ, Tên nhóm và Gmail phụ huynh."); return
            if "@" not in em or "." not in em.split("@")[-1]:
                info.config(text="Gmail phụ huynh chưa đúng định dạng."); return
            con2=connect()
            try:
                con2.execute("UPDATE students SET team=?, parent_email=?, group_name=? WHERE id=?",(t,em,g,sid))
                con2.execute("UPDATE parents SET email=? WHERE student_id=?",(em,sid))
                class_row=con2.execute("SELECT id FROM classes WHERE class_name=?",(live["class_name"],)).fetchone()
                if class_row:
                    con2.execute("UPDATE classes SET group_name=? WHERE id=?",(g,class_row["id"]))
                else:
                    con2.execute("INSERT INTO classes(class_name,homeroom_teacher,group_name) VALUES(?,?,?)",(live["class_name"],live["homeroom_teacher"],g))
                con2.commit()
                updated=con2.execute("SELECT * FROM students WHERE id=?",(sid,)).fetchone()
            except Exception as exc:
                con2.rollback(); con2.close(); messagebox.showerror("Không thể lưu",str(exc)); return
            con2.close()
            self.current_student=dict(updated)
            win.grab_release(); win.destroy()
            messagebox.showinfo("Đã cập nhật","Thông tin Tổ, Tên nhóm và Gmail phụ huynh đã được lưu.\nGiáo viên sẽ thấy dữ liệu mới ngay trong danh sách học sinh.")
            if after_save: after_save()
            else: self.student_home()
        self.button(win,"💾 LƯU VÀO HỒ SƠ GIÁO VIÊN",save,24,COLORS["green"]).pack(pady=15)
        self.button(win,"Thoát",lambda:(win.grab_release(),win.destroy(),self.show_login()),12,"#7f8c8d").pack()
        win.protocol("WM_DELETE_WINDOW", lambda:(win.grab_release(),win.destroy(),self.show_login()))

    def student_account_login(self,username,password,team,officer_only=False):
        username=username.strip(); password=password.strip(); team=team.strip()
        if not username or not password:
            messagebox.showwarning("Thiếu thông tin","Hãy nhập tài khoản và mật khẩu."); return
        con=connect(); row=con.execute("SELECT * FROM students WHERE student_username=? AND student_password_hash=?",(username,hash_pw(password))).fetchone()
        if not row:
            con.close(); messagebox.showerror("Đăng nhập","Tài khoản hoặc mật khẩu không đúng."); return
        saved_team=(row["team"] or "").strip()
        # Tài khoản nhập từ Excel có thể chưa có Tổ; cho phép đăng nhập lần đầu để cập nhật hồ sơ.
        if saved_team:
            if not team or saved_team.casefold()!=team.casefold():
                con.close(); messagebox.showerror("Sai Tổ","Tổ bạn nhập không khớp với hồ sơ hiện tại."); return
        if row["status"] not in ("approved","verified"):
            con.close(); messagebox.showwarning("Chưa được duyệt","Hồ sơ học sinh chưa được giáo viên phê duyệt."); return
        officer=bool(row["officer_role"])
        if officer_only and not officer:
            con.close(); messagebox.showerror("Không có quyền","Tài khoản này hiện không phải ban cán sự lớp."); return
        self.current_student=dict(row); con.close(); self.current_student["login_role"]="officer" if officer else "student"
        def after():
            self.student_home()
        if (not (row["team"] or "").strip()) or (not (row["parent_email"] or "").strip()) or (not (row["group_name"] or "").strip()):
            self.complete_first_login_profile(dict(row), after)
        else:
            self.student_home()

    def teacher_login(self, username, password):
        con = connect()
        row = con.execute(
            "SELECT * FROM teacher WHERE username=? AND password_hash=?",
            (username.strip(), hash_pw(password))
        ).fetchone()
        con.close()
        if row:
            self.teacher_dashboard()
        else:
            messagebox.showerror("Đăng nhập", "Sai tài khoản hoặc mật khẩu.")

    def change_teacher_password(self):
        old = simpledialog.askstring(
            "Đổi mật khẩu giáo viên", "Mật khẩu hiện tại:", show="*"
        )
        if old is None:
            return
        con = connect()
        row = con.execute(
            "SELECT password_hash FROM teacher WHERE id=1"
        ).fetchone()
        if not row or row["password_hash"] != hash_pw(old):
            con.close()
            messagebox.showerror("Lỗi", "Mật khẩu hiện tại không đúng.")
            return

        new = simpledialog.askstring(
            "Đổi mật khẩu giáo viên",
            "Mật khẩu mới (ít nhất 6 ký tự):",
            show="*"
        )
        if not new or len(new) < 6:
            con.close()
            messagebox.showwarning("Lưu ý", "Mật khẩu phải có ít nhất 6 ký tự.")
            return

        con.execute(
            "UPDATE teacher SET password_hash=? WHERE id=1",
            (hash_pw(new),)
        )
        con.commit()
        con.close()
        messagebox.showinfo("Thành công", "Đã đổi mật khẩu giáo viên.")

    def _check_saved_reminders(self):
        try:
            con=connect(); rows=con.execute("SELECT id,title,remind_at,note FROM chat_reminders WHERE done=0 ORDER BY remind_at LIMIT 20").fetchall()
            con.close()
            now_dt=datetime.now()
            for r in rows:
                try:
                    dt=datetime.strptime(r["remind_at"],"%Y-%m-%d %H:%M")
                    if dt <= now_dt:
                        con=connect(); con.execute("UPDATE chat_reminders SET done=1 WHERE id=?",(r["id"],)); con.commit(); con.close()
                        messagebox.showinfo("⏰ Nhắc hẹn giáo viên",r["title"]+(f"\n{r['note']}" if r["note"] else ""))
                    else:
                        self._schedule_reminder(r["title"],r["remind_at"],r["note"])
                except Exception: pass
        except Exception: pass

    # -------------------- TEACHER DASHBOARD --------------------
    def teacher_photo_avatar(self, parent, size=160):
        """Avatar giao vien: co giao dung trong lop, cam sach Toan; hien thi hinh tron."""
        try:
            import base64 as _b64
            from io import BytesIO as _BytesIO
            if PIL_OK:
                con = connect(); row = con.execute("SELECT avatar_path FROM teacher WHERE id=1").fetchone(); con.close()
                avatar_path = (row["avatar_path"] if row else "") or ""
                if avatar_path and os.path.exists(avatar_path):
                    im = Image.open(avatar_path).convert("RGBA")
                else:
                    raw = _b64.b64decode(TEACHER_AVATAR_B64)
                    im = Image.open(_BytesIO(raw)).convert("RGBA")
                im = im.resize((size, size), Image.LANCZOS)
                mask = Image.new("L", (size, size), 0)
                ImageDraw.Draw(mask).ellipse((0, 0, size-1, size-1), fill=255)
                im.putalpha(mask)
                photo = ImageTk.PhotoImage(im)
                lab = tk.Label(parent, image=photo, bg=parent.cget("bg"), bd=0, highlightthickness=0)
                lab.image = photo
                return lab
        except Exception:
            pass
        return self.avatar_image(parent, size, "teacher-math")

    def teacher_dashboard(self):
        """Dashboard V10 - giao dien moi theo mau yeu cau, khong dung bo cuc dashboard cu."""
        self.clear()
        self.configure(bg="#f3f7fc")
        try:
            self.state("zoomed")
        except Exception:
            pass
        self.minsize(1180, 760)

        # ---- thong ke ----
        con = connect()
        total = con.execute("SELECT COUNT(*) n FROM students").fetchone()["n"]
        classes = con.execute("SELECT COUNT(*) n FROM classes").fetchone()["n"]
        officers = con.execute("SELECT COUNT(*) n FROM class_officers").fetchone()["n"]
        try:
            parents = con.execute("SELECT COUNT(*) n FROM parents").fetchone()["n"]
        except Exception:
            parents = 0
        try:
            pending = con.execute("SELECT COUNT(*) n FROM students WHERE status='pending'").fetchone()["n"]
        except Exception:
            pending = 0
        try:
            pending_par = con.execute("SELECT COUNT(*) n FROM parent_requests WHERE status='pending'").fetchone()["n"]
        except Exception:
            pending_par = 0
        con.close()

        # ---- khung tong ----
        shell = tk.Frame(self, bg="#f3f7fc")
        shell.pack(fill="both", expand=True)

        # ===== SIDEBAR =====
        side = tk.Frame(shell, bg="#103b78", width=275)
        side.pack(side="left", fill="y")
        side.pack_propagate(False)

        # Khu vực menu có thanh cuộn riêng; nút Đăng xuất luôn cố định ở đáy,
        # không bị cuộn khuất trên màn hình thấp.
        side_body = tk.Frame(side, bg="#103b78")
        side_body.pack(fill="both", expand=True)
        side_canvas = tk.Canvas(side_body, bg="#103b78", highlightthickness=0, bd=0)
        side_scroll = tk.Scrollbar(side_body, orient="vertical", command=side_canvas.yview, width=16)
        side_canvas.configure(yscrollcommand=side_scroll.set)
        side_canvas.pack(side="left", fill="both", expand=True)
        side_scroll.pack(side="right", fill="y")
        side_inner = tk.Frame(side_canvas, bg="#103b78")
        side_id = side_canvas.create_window((0,0), window=side_inner, anchor="nw")
        side_inner.bind("<Configure>", lambda e: side_canvas.configure(scrollregion=side_canvas.bbox("all")))
        side_canvas.bind("<Configure>", lambda e: side_canvas.itemconfigure(side_id, width=e.width))

        # avatar co giao: anh that nhung trong code, khong phu thuoc cot gender/avatar_seed
        avatar_wrap = tk.Frame(side_inner, bg="#103b78")
        avatar_wrap.pack(fill="x", pady=(18, 8))
        self.teacher_photo_avatar(avatar_wrap, 160).pack(pady=2)
        tk.Label(avatar_wrap, text="Giáo viên chủ nhiệm", bg="#103b78", fg="white",
                 font=("Arial", 14, "bold")).pack(pady=(8, 2))
        tk.Label(avatar_wrap, text=TEACHER_NAME, bg="#103b78", fg="#ffd52f",
                 font=("Arial", 15, "bold")).pack()
