    def show_hero_placeholder(self, parent):
        return None

    def manage_classes(self):
        self.clear()
        self.header("🏫 QUẢN LÝ LỚP", "Có thể tạo nhiều lớp")

        con = connect()
        rows = con.execute(
            "SELECT * FROM classes ORDER BY class_name"
        ).fetchall()
        con.close()

        tr = self.tree(
            ("id", "class_name", "teacher", "group", "avatar"),
            ("ID", "Lớp", "Giáo viên chủ nhiệm", "Tên nhóm", "Ảnh nhóm"),
            [60, 180, 220, 220, 110]
        )
        for r in rows:
            tr.insert("", "end", values=(
                r["id"], r["class_name"], r["homeroom_teacher"], r["group_name"] or "Nhóm lớp",
                "Đã có" if (r["group_avatar_path"] or "").strip() else "Mặc định"
            ))

        panel = tk.Frame(self, bg=COLORS["bg"])
        panel.pack(pady=5)

        class_name = tk.StringVar()
        teacher = tk.StringVar(value=TEACHER_NAME)
        group_name = tk.StringVar(value="Nhóm lớp")

        tk.Label(panel, text="Tên lớp:", bg=COLORS["bg"]).pack(
            side="left", padx=4)
        tk.Entry(panel, textvariable=class_name, width=20).pack(
            side="left", padx=4)
        tk.Label(panel, text="Giáo viên chủ nhiệm:", bg=COLORS["bg"]).pack(side="left", padx=4)
        tk.Entry(panel, textvariable=teacher, width=24).pack(side="left", padx=4)
        tk.Label(panel, text="Tên nhóm:", bg=COLORS["bg"]).pack(side="left", padx=4)
        tk.Entry(panel, textvariable=group_name, width=18).pack(side="left", padx=4)

        def add_class():
            name = class_name.get().strip()
            t = teacher.get().strip()
            g = group_name.get().strip() or "Nhóm lớp"
            if not name or not t:
                messagebox.showwarning("Thiếu", "Nhập tên lớp và giáo viên chủ nhiệm.")
                return
            con2 = connect()
            try:
                con2.execute(
                    "INSERT INTO classes(class_name,homeroom_teacher,group_name) VALUES(?,?,?)",
                    (name, t, g)
                )
                con2.commit()
            except sqlite3.IntegrityError:
                con2.close()
                messagebox.showerror("Lỗi", "Lớp này đã tồn tại.")
                return
            con2.close()
            messagebox.showinfo("Thành công", "Đã thêm lớp.")
            self.manage_classes()

        self.button(panel, "➕ Thêm lớp", add_class, 15, COLORS["green"]).pack(
            side="left", padx=5)

        def delete_class():
            sel = tr.selection()
            if not sel:
                messagebox.showwarning("Chọn", "Hãy chọn lớp.")
                return
            class_id = tr.item(sel[0])["values"][0]
            con2 = connect()
            con2.execute("DELETE FROM classes WHERE id=?", (class_id,))
            con2.commit()
            con2.close()
            self.manage_classes()

        self.button(panel,"✏️ Đổi tên lớp",lambda:self.rename_class(tr),15,COLORS["orange"]).pack(side="left",padx=5)
        self.button(panel,"👩‍🏫 Đổi GVCN",lambda:self.edit_class_teacher(tr),13,COLORS["blue"]).pack(side="left",padx=5)
        self.button(panel,"👥 Đổi tên nhóm",lambda:self.edit_group_name(tr),15,COLORS["purple"]).pack(side="left",padx=5)
        self.button(panel,"🖼️ Đổi ảnh nhóm",lambda:self.edit_group_avatar(tr),15,COLORS["cyan"]).pack(side="left",padx=5)
        self.button(panel,"🗑 Xóa lớp",delete_class,13,COLORS["red"]).pack(side="left",padx=5)

        self.button(
            self, "Quay lại", self.teacher_dashboard, 15, "#7f8c8d"
        ).pack(pady=8)

    def edit_class_teacher(self, tree):
        sel=tree.selection()
        if not sel: return
        vals=tree.item(sel[0])["values"]; old=vals[2]
        new=simpledialog.askstring("Đổi giáo viên chủ nhiệm", "Tên giáo viên chủ nhiệm mới:", initialvalue=old)
        if new is None: return
        new=new.strip()
        if not new: return
        con=connect()
        con.execute("UPDATE classes SET homeroom_teacher=? WHERE id=?",(new,vals[0]))
        con.execute("UPDATE students SET homeroom_teacher=? WHERE class_name=?",(new,vals[1]))
        con.execute("UPDATE parent_requests SET homeroom_teacher=? WHERE class_name=?",(new,vals[1]))
        con.commit(); con.close()
        messagebox.showinfo("Đã cập nhật", f"Đã đổi GVCN của lớp {vals[1]} thành {new}.")
        self.manage_classes()

    def edit_group_name(self, tree):
        sel=tree.selection()
        if not sel: return
        vals=tree.item(sel[0])["values"]; old=vals[3] if len(vals)>3 else "Nhóm lớp"
        new=simpledialog.askstring("Đổi tên nhóm", "Tên nhóm mới:", initialvalue=old)
        if new is None: return
        new=new.strip() or "Nhóm lớp"
        con=connect(); con.execute("UPDATE classes SET group_name=? WHERE id=?",(new,vals[0])); con.commit(); con.close()
        self.manage_classes()

    def edit_group_avatar(self, tree):
        sel=tree.selection()
        if not sel:
            messagebox.showwarning("Chọn lớp", "Hãy chọn lớp cần đổi ảnh đại diện nhóm.")
            return
        vals=tree.item(sel[0])["values"]
        class_id, class_name = vals[0], vals[1]
        f=filedialog.askopenfilename(
            title=f"Chọn ảnh đại diện cho nhóm {class_name}",
            filetypes=[("Ảnh PNG/JPG/WEBP", "*.png *.jpg *.jpeg *.webp"), ("Tất cả", "*.*")]
        )
        if not f:
            return
        try:
            ext=Path(f).suffix.lower() or ".png"
            avatar_dir=os.path.join(BASE_DIR, "group_avatars")
            os.makedirs(avatar_dir, exist_ok=True)
            dest=os.path.join(avatar_dir, f"group_{class_id}{ext}")
            shutil.copy2(f, dest)
            con=connect()
            con.execute("UPDATE classes SET group_avatar_path=? WHERE id=?", (dest, class_id))
            con.commit(); con.close()
            messagebox.showinfo("Đã cập nhật", f"Đã đổi ảnh đại diện nhóm {class_name}.")
            self.manage_classes()
        except Exception as e:
            messagebox.showerror("Lỗi ảnh nhóm", f"Không thể lưu ảnh đại diện nhóm.\n\n{e}")

    def rename_class(self, tree):
        sel=tree.selection()
        if not sel:return
        vals=tree.item(sel[0])["values"]; old=vals[1]; new=simpledialog.askstring("Đổi tên lớp",f"Tên lớp hiện tại: {old}\nNhập tên lớp mới:",initialvalue=old)
        if new is None:return
        new=new.strip();
        if not new or new==old:return
        con=connect()
        try:
            con.execute("UPDATE classes SET class_name=? WHERE id=?",(new,vals[0])); con.execute("UPDATE students SET class_name=? WHERE class_name=?",(new,old)); con.execute("UPDATE parent_requests SET class_name=? WHERE class_name=?",(new,old)); con.commit()
        except sqlite3.IntegrityError:
            con.close(); messagebox.showerror("Lỗi","Tên lớp mới đã tồn tại."); return
        con.close(); messagebox.showinfo("Đã đổi tên",f"Đã đổi {old} → {new}. Hồ sơ, điểm, nhiệm vụ và ban cán sự vẫn giữ nguyên."); self.manage_classes()

    # -------------------- STUDENT REGISTER --------------------
    def student_register(self):
        self.clear()
        self.header(
            "🎓 ĐĂNG KÝ HỌC SINH",
            "Học sinh tự tạo tài khoản + mật khẩu → gửi giáo viên chủ nhiệm → chờ phê duyệt"
        )

        card = tk.Frame(self, bg="white", bd=1, relief="solid")
        card.pack(pady=10, ipadx=35, ipady=20)

        labels = [
            "Họ tên học sinh",
            "Tên đăng nhập học sinh",
            "Mật khẩu học sinh",
            "Lớp",
            "Tổ",
            "Giáo viên chủ nhiệm",
            "Họ tên phụ huynh",
            "Email phụ huynh",
        ]
        entries = []

        for i, label in enumerate(labels):
            tk.Label(card,text=label+":",bg="white",font=("Arial",10,"bold")).grid(
                row=i,column=0,sticky="e",padx=10,pady=7
            )
            e=tk.Entry(card,width=42,show="*" if "Mật khẩu" in label else "")
            e.grid(row=i,column=1,padx=10,pady=7)
            entries.append(e)

        entries[5].insert(0, TEACHER_NAME)

        def submit():
            values=[e.get().strip() for e in entries]
            if not all(values):
                messagebox.showwarning(
                    "Thiếu thông tin",
                    "Hãy nhập đầy đủ họ tên, tên đăng nhập, mật khẩu, lớp, tổ, "
                    "giáo viên chủ nhiệm, họ tên phụ huynh và email."
                )
                return
            if len(values[2]) < 6:
                messagebox.showwarning("Mật khẩu","Mật khẩu học sinh phải có ít nhất 6 ký tự.")
                return
            if "@" not in values[7]:
                messagebox.showwarning("Email","Email phụ huynh chưa hợp lệ.")
                return

            con=connect()
            try:
                exists=con.execute(
                    "SELECT 1 FROM students WHERE lower(student_username)=lower(?) LIMIT 1",
                    (values[1],)
                ).fetchone()
                if exists:
                    messagebox.showwarning("Tên đăng nhập","Tên đăng nhập học sinh đã tồn tại.")
                    return

                con.execute("""
                    INSERT INTO students(
                        name,class_name,team,homeroom_teacher,
                        parent_name,parent_email,
                        student_username,student_password_hash,student_password_display,
                        status,created_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,'pending',?)
                """,(
                    values[0],values[3],values[4],values[5],
                    values[6],values[7],
                    values[1],hash_pw(values[2]),values[2],now()
                ))
                con.commit()
            except Exception as e:
                con.rollback()
                messagebox.showerror("Đăng ký thất bại",f"Không thể lưu hồ sơ học sinh.\n\n{e}")
                return
            finally:
                con.close()

            messagebox.showinfo(
                "Đã gửi",
                "Hồ sơ học sinh đã gửi giáo viên phê duyệt.\n"
                "Tên đăng nhập và mật khẩu bạn vừa tạo sẽ được giữ nguyên sau khi được duyệt."
            )
            self.show_login()

        self.button(card,"📨 GỬI GIÁO VIÊN PHÊ DUYỆT",submit,30,COLORS["green"]).grid(
            row=len(labels),column=0,columnspan=2,pady=13
        )
        self.button(self,"Quay lại",self.show_login,15,"#7f8c8d").pack()

    def teacher_qr_manager(self):
        """Chỉ giáo viên mới có màn hình tạo/hiển thị QR."""
        self.clear()
        teacher_code=get_teacher_code()
        self.header("▣ TẠO MÃ QR CHO PHỤ HUYNH",
                     f"Chỉ giáo viên được xem QR. Giáo viên gửi QR cho học sinh/phụ huynh | Mã GV: {teacher_code}")

        info=tk.Frame(self,bg="#eef5ff",bd=1,relief="solid")
        info.pack(fill="x",padx=28,pady=(0,12))
        tk.Label(info,text=f"🔐 MÃ GIÁO VIÊN: {teacher_code}",
                 bg="#eef5ff",fg="#173f7a",font=("Arial",15,"bold")).pack(side="left",padx=16,pady=10)
        self.button(info,"🔄 Đổi mã giáo viên",self.teacher_code_dialog,16,COLORS["purple"]).pack(side="right",padx=10,pady=6)

        con=connect()
        rows=con.execute("""
            SELECT s.id,s.name,s.class_name,s.access_code,
                   p.password_display,p.email
            FROM students s
            LEFT JOIN parents p ON p.student_id=s.id
            WHERE s.status='approved'
            ORDER BY s.class_name,s.name
        """).fetchall()
        con.close()

        wrap=tk.Frame(self,bg="white",bd=1,relief="solid")
        wrap.pack(fill="both",expand=True,padx=28,pady=8)
        tk.Label(wrap,text="DANH SÁCH HỌC SINH ĐÃ ĐƯỢC DUYỆT",
                 bg="white",fg=COLORS["navy"],font=("Arial",14,"bold")).pack(anchor="w",padx=14,pady=10)

        tree_wrap=tk.Frame(wrap,bg="white"); tree_wrap.pack(fill="both",expand=True,padx=10,pady=5)
        tr=ttk.Treeview(tree_wrap,columns=("id","name","class","code","parent"),show="headings",height=12)
        vs=tk.Scrollbar(tree_wrap,orient="vertical",command=tr.yview); tr.configure(yscrollcommand=vs.set)
        tr.pack(side="left",fill="both",expand=True); vs.pack(side="right",fill="y")
        for col,title,w in [("id","ID",55),("name","Học sinh",220),("class","Lớp",100),
                            ("code","Mã xác nhận",150),("parent","Tài khoản PH",260)]:
            tr.heading(col,text=title); tr.column(col,width=w,anchor="center")
        for r in rows:
            tr.insert("", "end", iid=str(r["id"]),
                      values=(r["id"],r["name"],r["class_name"],r["access_code"] or "Chưa có",
                              r["email"] or "Chưa cấp tài khoản"))

        def create_selected_qr():
            sel=tr.selection()
            if not sel:
                messagebox.showwarning("Tạo QR","Hãy chọn học sinh đã được duyệt.")
                return
            sid=int(sel[0])
            con2=connect()
            st=con2.execute("SELECT * FROM students WHERE id=?",(sid,)).fetchone()
            par=con2.execute("SELECT * FROM parents WHERE student_id=?",(sid,)).fetchone()
            con2.close()
            if not st:
                messagebox.showerror("Tạo QR","Không tìm thấy học sinh."); return
            if not st["access_code"]:
                messagebox.showwarning("Tạo QR","Học sinh này chưa có mã xác nhận. Hãy xác nhận phụ huynh trước.")
                return
            if not par or not par["password_display"]:
                messagebox.showwarning("Tạo QR","Học sinh này chưa có mật khẩu phụ huynh. Hãy xác nhận phụ huynh trước.")
                return
            self.show_teacher_qr_window(dict(st),dict(par),teacher_code)

        # Thanh thao tác cố định ở đáy màn hình, không bị bảng học sinh đẩy xuống
        # hoặc khuất bởi thanh taskbar trên màn hình thấp.
        actions=tk.Frame(self,bg=COLORS["bg"])
        actions.pack(side="bottom",fill="x",padx=20,pady=(5,10))
        self.button(actions,"▣ TẠO / HIỆN QR CHO HỌC SINH ĐÃ CHỌN",
                     create_selected_qr,34,COLORS["purple"]).pack(side="left",padx=6,ipady=2)
        self.button(actions,"↩ Quay lại",self.teacher_dashboard,14,"#7f8c8d").pack(side="right",padx=6,ipady=2)

    def show_teacher_qr_window(self,student,parent,teacher_code):
        win=tk.Toplevel(self)
        win.title("▣ QR xác nhận phụ huynh — chỉ giáo viên")
        win.geometry("760x900")
        win.minsize(620,700)
        win.configure(bg="white")

        # Khung cuộn để toàn bộ nội dung luôn xem được trên màn hình nhỏ.
        outer=tk.Frame(win,bg="white"); outer.pack(fill="both",expand=True)
        canvas=tk.Canvas(outer,bg="white",highlightthickness=0)
        bar=tk.Scrollbar(outer,orient="vertical",command=canvas.yview)
        canvas.configure(yscrollcommand=bar.set)
        canvas.pack(side="left",fill="both",expand=True)
        bar.pack(side="right",fill="y")
        body=tk.Frame(canvas,bg="white")
        body_id=canvas.create_window((0,0),window=body,anchor="nw")
        body.bind("<Configure>",lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>",lambda e: canvas.itemconfigure(body_id,width=e.width))

        tk.Label(body,text="▣ QR XÁC NHẬN PHỤ HUYNH",
                 bg="white",fg=COLORS["navy"],font=("Arial",20,"bold")).pack(pady=(16,6))
        tk.Label(body,text=f"Học sinh: {student['name']}  •  Lớp: {student['class_name']}",
                 bg="white",fg="#444",font=("Arial",11,"bold"),wraplength=650,
                 justify="center").pack(pady=4)

        box=tk.Frame(body,bg="#f6f9ff",bd=1,relief="solid")
        box.pack(fill="x",padx=30,pady=10)
        for title,val,col in [
            ("MÃ GIÁO VIÊN",teacher_code,"#173f7a"),
            ("MÃ XÁC NHẬN HỌC SINH",student["access_code"],"#bd2727"),
            ("MẬT KHẨU PHỤ HUYNH — CHỈ GIÁO VIÊN XEM",parent["password_display"],"#7a4600")
        ]:
            tk.Label(box,text=title,bg="#f6f9ff",fg="#555",
                     font=("Arial",9,"bold")).pack(pady=(9,0))
            tk.Label(box,text=str(val),bg="#f6f9ff",fg=col,
                     font=("Arial",20,"bold"),wraplength=620,
                     justify="center").pack(pady=(1,9),padx=12)

        payload=(f"XAC_NHAN_PHU_HUYNH\\nMa giao vien: {teacher_code}\\n"
                 f"Ma xac nhan: {student['access_code']}\\n"
                 f"Mat khau phu huynh: {parent['password_display']}\\n"
                 "Chi dung thong tin nay de dang nhap tai khoan phu huynh.")
        qr_file=os.path.join(BASE_DIR,f"QR_phu_huynh_{student['id']}.png")

        if QR_OK:
            image=qrcode.make(payload)
            image.save(qr_file)

            # Không resize bằng nội suy mờ; giữ QR nguyên nét và chỉ giới hạn
            # kích thước hiển thị bằng thumbnail NEAREST nếu cần.
            try:
                from PIL import ImageTk, Image
                qr_img=image.convert("RGB")
                max_side=360
                if max(qr_img.size)>max_side:
                    qr_img=qr_img.resize((max_side,max_side),Image.Resampling.NEAREST)
                photo=ImageTk.PhotoImage(qr_img)
                lab=tk.Label(body,image=photo,bg="white")
                lab.image=photo
                lab.pack(pady=8)
            except Exception:
                tk.Label(body,text=f"QR đã lưu tại:\n{qr_file}",
                         bg="white",fg="#666").pack(pady=25)

            tk.Label(body,
                     text="⚠ QR CHỈ HIỂN THỊ CHO GIÁO VIÊN\\n"
                          "Giáo viên gửi QR cho học sinh. Phụ huynh dùng điện thoại quét QR "
                          "để xem thông tin xác nhận và mật khẩu.",
                     bg="#fff8e8",fg="#7a4600",font=("Arial",10,"bold"),
                     wraplength=650,justify="center",bd=1,relief="solid",
                     padx=12,pady=10).pack(fill="x",padx=30,pady=8)

            def copy_path():
                self.clipboard_clear()
                self.clipboard_append(qr_file)
                self.update()
                messagebox.showinfo("QR","Đã sao chép đường dẫn tệp QR.")

            self.button(body,"📋 SAO CHÉP ĐƯỜNG DẪN QR",copy_path,18,COLORS["blue"]).pack(pady=5)
            self.button(body,"🔄 TẠO LẠI QR",
                        lambda:self._regenerate_parent_qr(win,student,teacher_code,student["access_code"]),
                        16,COLORS["purple"]).pack(pady=5)
        else:
            tk.Label(body,
                     text="Máy chưa có thư viện qrcode. Cài qrcode[pil] để tạo QR.",
                     bg="white",fg="#bd2727",font=("Arial",11,"bold"),
                     wraplength=620,justify="center").pack(pady=30)

        self.button(body,"Đóng",win.destroy,14,"#7f8c8d").pack(pady=(8,18))
        canvas.bind_all("<MouseWheel>",lambda e: canvas.yview_scroll(int(-e.delta/120),"units"))
        win.protocol("WM_DELETE_WINDOW",lambda:(canvas.unbind_all("<MouseWheel>"),win.destroy()))

    def pending_parents(self):
        self.clear()
        teacher_code=get_teacher_code()
        self.header(
            "👨‍👩‍👧 XÁC NHẬN PHỤ HUYNH",
            f"Giáo viên kiểm tra → xác nhận phụ huynh → tạo mã + QR | Mã giáo viên: {teacher_code}"
        )
        info=tk.Frame(self,bg="#eef5ff",bd=1,relief="solid")
        info.pack(fill="x",padx=28,pady=(0,10))
        tk.Label(info,text=f"🔐 MÃ XÁC NHẬN CỦA GIÁO VIÊN:  {teacher_code}",
                 bg="#eef5ff",fg="#173f7a",font=("Arial",15,"bold")).pack(side="left",padx=16,pady=10)
        self.button(info,"🔄 Tạo mã giáo viên mới",self.teacher_code_dialog,24,COLORS["purple"]).pack(side="right",padx=10,pady=6)

        con=connect()
        rows=con.execute("SELECT * FROM parent_requests WHERE status='pending' ORDER BY id DESC").fetchall()
        con.close()
        tr=self.tree(
            ("id","parent","email","child","class","team","teacher"),
            ("ID","Tên phụ huynh","Email","Tên con","Lớp","Tổ","Giáo viên chủ nhiệm"),
            [55,180,250,180,90,70,220]
        )
        for r in rows:
            tr.insert("", "end", values=(r["id"],r["parent_name"],r["parent_email"],r["student_name"],r["class_name"],r["team"],r["homeroom_teacher"]))

        def delete_request_and_accounts():
            sel=tr.selection()
            if not sel:
                messagebox.showwarning("Chọn","Hãy chọn yêu cầu phụ huynh cần xóa.")
                return
            rid=int(tr.item(sel[0])["values"][0])
            con2=connect()
            try:
                req=con2.execute("SELECT * FROM parent_requests WHERE id=?",(rid,)).fetchone()
                if not req:
                    messagebox.showerror("Lỗi","Không tìm thấy yêu cầu.")
                    return

                # Tìm học sinh theo tên + lớp, sau đó xóa cả tài khoản HS và PH.
                student=con2.execute(
                    "SELECT id,name FROM students WHERE name=? AND class_name=? ORDER BY id DESC LIMIT 1",
                    (req["student_name"],req["class_name"])
                ).fetchone()

                confirm=messagebox.askyesno(
                    "⚠ XÓA CẢ HỌC SINH + PHỤ HUYNH",
                    f"Xóa yêu cầu của phụ huynh {req['parent_name']} và học sinh {req['student_name']}?\n\n"
                    "Hệ thống sẽ xóa cả tài khoản học sinh, tài khoản phụ huynh và yêu cầu xác nhận liên quan."
                )
                if not confirm:
                    return

                # Xóa dữ liệu liên quan trước để tránh tài khoản mồ côi.
                if student:
                    sid=student["id"]
                    for table in ("parents","class_officers"):
                        try:
                            con2.execute(f"DELETE FROM {table} WHERE student_id=?",(sid,))
                        except sqlite3.OperationalError:
                            pass
                    for table in ("scores","task_completions"):
                        try:
                            con2.execute(f"DELETE FROM {table} WHERE student_id=?",(sid,))
                        except sqlite3.OperationalError:
                            pass
                    try:
                        con2.execute("DELETE FROM students WHERE id=?",(sid,))
                    except sqlite3.OperationalError:
                        pass

                con2.execute("DELETE FROM parent_requests WHERE id=?",(rid,))
                con2.commit()
                messagebox.showinfo("Đã xóa","Đã xóa cả hồ sơ và tài khoản học sinh/phụ huynh liên quan.")
            except Exception as exc:
                con2.rollback()
                messagebox.showerror("Lỗi xóa",f"Không thể xóa hồ sơ:\n{exc}")
            finally:
                con2.close()

            self.pending_parents()

        def approve():
            sel=tr.selection()
            if not sel:
                messagebox.showwarning("Chọn","Hãy chọn yêu cầu phụ huynh."); return
            rid=tr.item(sel[0])["values"][0]
            con2=connect()
            req=con2.execute("SELECT * FROM parent_requests WHERE id=?",(rid,)).fetchone()
            student=con2.execute(
                "SELECT * FROM students WHERE name=? AND class_name=? ORDER BY id DESC LIMIT 1",
                (req["student_name"],req["class_name"])
            ).fetchone()
            if not student:
                con2.close()
                messagebox.showerror("Không tìm thấy","Không tìm thấy học sinh khớp tên và lớp. Giáo viên hãy kiểm tra lại.")
                return
            access_code=student["access_code"] or make_code()
            if student["status"] != "approved":
                con2.execute("UPDATE students SET status='approved',access_code=?,approved_at=? WHERE id=?",
                             (access_code,now(),student["id"]))
            parent_username=req["parent_username"] or req["parent_email"]
            parent_password_hash=req["parent_password_hash"]
            parent_password_display=req["parent_password_display"]
            if not parent_password_hash:
                con2.close()
                messagebox.showerror(
                    "Thiếu tài khoản phụ huynh",
                    "Phụ huynh chưa đăng ký tên đăng nhập và mật khẩu.\n"
                    "Yêu cầu này không thể cấp tài khoản."
                )
                return

            con2.execute(
                """INSERT OR REPLACE INTO parents(
                    student_id,email,username,password_hash,password_display,must_change,verified
                ) VALUES(?,?,?,?,?,?,0)""",
                (student["id"],req["parent_email"],parent_username,parent_password_hash,parent_password_display,0)
            )
            parent_temp=parent_password_display
            con2.execute("UPDATE parent_requests SET status='approved',approved_at=? WHERE id=?",(now(),rid))
            con2.commit()
            student2=con2.execute("SELECT * FROM students WHERE id=?",(student["id"],)).fetchone()
            con2.close()
            self.show_parent_confirmation_package(dict(student2),req["parent_name"],req["parent_email"],parent_temp,teacher_code,access_code)
            self.pending_parents()

        # Thanh nút cố định ở đáy: luôn nhìn thấy dù bảng dữ liệu chiếm toàn màn hình.
        actions=tk.Frame(self,bg=COLORS["bg"])
        actions.pack(side="bottom",fill="x",padx=20,pady=(5,10))
        self.button(actions,"✅ XÁC NHẬN PHỤ HUYNH + CẤP MK + TẠO QR",
                     approve,48,COLORS["green"]).pack(side="left",padx=6,ipady=2)
        self.button(actions,"🗑 XÓA CẢ HS + PH",
                     delete_request_and_accounts,22,COLORS["red"]).pack(side="left",padx=6,ipady=2)
        self.button(actions,"Quay lại",self.teacher_dashboard,15,"#7f8c8d").pack(side="right",padx=6,ipady=2)

    def teacher_code_dialog(self):
        win=tk.Toplevel(self); win.title("Mã xác nhận của giáo viên"); win.geometry("560x300"); win.configure(bg="white")
        code=get_teacher_code()
        tk.Label(win,text="🔐 MÃ GIÁO VIÊN",bg="white",fg=COLORS["navy"],font=("Arial",18,"bold")).pack(pady=(24,8))
        tk.Label(win,text=code,bg="white",fg="#bd2727",font=("Arial",30,"bold")).pack(pady=5)
        tk.Label(win,text="Mã này được dùng kèm mã học sinh trong gói xác nhận phụ huynh và QR.",
                 bg="white",fg="#555",font=("Arial",10),wraplength=480,justify="center").pack(pady=8)
        def regenerate():
            new_code=make_teacher_code()
            con=connect(); con.execute("UPDATE teacher SET verification_code=? WHERE id=1",(new_code,)); con.commit(); con.close()
            messagebox.showinfo("Đã tạo mã",f"Mã giáo viên mới: {new_code}\n\nQR tạo sau thời điểm này sẽ dùng mã mới.")
            win.destroy(); self.pending_parents()
        self.button(win,"🔄 Tạo mã giáo viên mới",regenerate,16,COLORS["purple"]).pack(pady=7)
        self.button(win,"Đóng",win.destroy,13,"#7f8c8d").pack(pady=5)

    def show_parent_confirmation_package(self,student,parent_name,parent_email,parent_temp,teacher_code,access_code):
        win=tk.Toplevel(self)
        win.title("Gói xác nhận phụ huynh — chỉ giáo viên")
        win.geometry("760x920")
        win.minsize(620,700)
        win.configure(bg="white")

        outer=tk.Frame(win,bg="white"); outer.pack(fill="both",expand=True)
        canvas=tk.Canvas(outer,bg="white",highlightthickness=0)
        bar=tk.Scrollbar(outer,orient="vertical",command=canvas.yview)
        canvas.configure(yscrollcommand=bar.set)
        canvas.pack(side="left",fill="both",expand=True)
        bar.pack(side="right",fill="y")
        body=tk.Frame(canvas,bg="white")
        body_id=canvas.create_window((0,0),window=body,anchor="nw")
        body.bind("<Configure>",lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>",lambda e: canvas.itemconfigure(body_id,width=e.width))

        tk.Label(body,text="✅ ĐÃ XÁC NHẬN PHỤ HUYNH",
                 bg="white",fg="#17854a",font=("Arial",20,"bold")).pack(pady=(15,8))
        tk.Label(body,
                 text=f"Phụ huynh: {parent_name}\\nEmail: {parent_email}\\n"
                      f"Học sinh: {student['name']}  •  Lớp: {student['class_name']}",
                 bg="white",font=("Arial",11),justify="center",
                 wraplength=650).pack(pady=6)

        box=tk.Frame(body,bg="#f6f9ff",bd=1,relief="solid")
        box.pack(fill="x",padx=28,pady=10)
        for title,val,col in [
            ("MÃ GIÁO VIÊN",teacher_code,"#173f7a"),
            ("MÃ XÁC NHẬN HỌC SINH",access_code,"#bd2727"),
            ("MẬT KHẨU PHỤ HUYNH — CHỈ GIÁO VIÊN XEM",parent_temp,"#7a4600")
        ]:
            tk.Label(box,text=title,bg="#f6f9ff",fg="#555",
                     font=("Arial",9,"bold")).pack(pady=(10,0))
            tk.Label(box,text=str(val),bg="#f6f9ff",fg=col,
                     font=("Arial",20,"bold"),wraplength=620,
                     justify="center").pack(pady=(1,10),padx=12)

        payload=("XAC_NHAN_PHU_HUYNH\\n"
                 f"Ma giao vien: {teacher_code}\\n"
                 f"Ma xac nhan: {access_code}\\n"
                 f"Mat khau phu huynh: {parent_temp or 'Chưa có tài khoản PH'}\\n"
                 "Chi dung thong tin nay de dang nhap tai khoan phu huynh.")
        qr_file=os.path.join(BASE_DIR,f"QR_phu_huynh_{student['id']}.png")

        if QR_OK:
            image=qrcode.make(payload)
            image.save(qr_file)
            try:
                from PIL import ImageTk, Image
                qr_img=image.convert("RGB")
                max_side=360
                if max(qr_img.size)>max_side:
                    qr_img=qr_img.resize((max_side,max_side),Image.Resampling.NEAREST)
                photo=ImageTk.PhotoImage(qr_img)
                lab=tk.Label(body,image=photo,bg="white")
                lab.image=photo
                lab.pack(pady=8)
            except Exception:
                tk.Label(body,text=f"QR đã tạo tại:\n{qr_file}",
                         bg="white",fg="#666").pack(pady=20)

            tk.Label(body,
                     text="📱 GIÁO VIÊN GỬI QR CHO HỌC SINH / PHỤ HUYNH\\n"
                          "Phụ huynh dùng điện thoại quét QR. Tài khoản học sinh "
                          "không hiển thị mật khẩu phụ huynh.",
                     bg="#fff8e8",fg="#7a4600",font=("Arial",10,"bold"),
                     wraplength=650,justify="center",bd=1,relief="solid",
                     padx=12,pady=10).pack(fill="x",padx=28,pady=8)
            tk.Label(body,text=f"QR đã lưu: {qr_file}",bg="white",fg="#555",
                     font=("Arial",9),wraplength=650,justify="center").pack(pady=3)
        else:
            tk.Label(body,
                     text="Chưa tạo được QR vì máy chưa có thư viện qrcode.\\n"
                          "Mã giáo viên + mã xác nhận học sinh vẫn dùng được.",
                     bg="white",fg="#9a5b00",justify="center",
                     wraplength=650).pack(pady=25)

        tk.Label(body,
                 text="Mật khẩu phụ huynh ở trên CHỈ dành cho giáo viên.\\n"
                      "Giáo viên gửi QR; phụ huynh quét QR bằng điện thoại để nhận thông tin cần thiết.",
                 bg="white",fg="#333",font=("Arial",10,"bold"),
                 justify="center",wraplength=650).pack(pady=10)

        if QR_OK:
            self.button(body,"📋 SAO CHÉP ĐƯỜNG DẪN QR",
                        lambda:self._copy_qr_path(qr_file),18,COLORS["blue"]).pack(pady=5)
            self.button(body,"🔄 TẠO LẠI QR",
                        lambda:self._regenerate_parent_qr(win,student,teacher_code,access_code),
                        18,COLORS["purple"]).pack(pady=5)
        self.button(body,"Đóng",win.destroy,14,"#7f8c8d").pack(pady=(7,18))

        canvas.bind_all("<MouseWheel>",lambda e: canvas.yview_scroll(int(-e.delta/120),"units"))
        win.protocol("WM_DELETE_WINDOW",lambda:(canvas.unbind_all("<MouseWheel>"),win.destroy()))

    def _copy_qr_path(self,qr_file):
        self.clipboard_clear()
        self.clipboard_append(qr_file)
        self.update()
        messagebox.showinfo("QR","Đã sao chép đường dẫn tệp QR.")

    def _regenerate_parent_qr(self,win,student,teacher_code,access_code):
        if not QR_OK:
            messagebox.showwarning("QR","Máy chưa có thư viện qrcode."); return
        con=connect()
        parent=con.execute("SELECT password_display FROM parents WHERE student_id=?",(student["id"],)).fetchone()
        con.close()
        parent_temp=(parent["password_display"] if parent else "")
        payload=(
            "XAC_NHAN_PHU_HUYNH\\n"
            f"Ma giao vien: {teacher_code}\\n"
            f"Ma xac nhan: {access_code}\\n"
            f"Mat khau phu huynh: {parent_temp}\\n"
            "Chi dung thong tin nay de dang nhap tai khoan phu huynh."
        )
        image=qrcode.make(payload)
        qr_file=os.path.join(BASE_DIR,f"QR_phu_huynh_{student['id']}.png"); image.save(qr_file)
        messagebox.showinfo("Đã tạo QR",f"QR dành cho phụ huynh đã được tạo lại:\n{qr_file}\n\n"
                                         "Chỉ cửa sổ giáo viên hiển thị QR. Phụ huynh dùng điện thoại quét QR để xem mật khẩu.")

    # -------------------- PENDING --------------------
    def pending_students(self):
        self.clear()
        self.header("📥 HỒ SƠ CHỜ DUYỆT", "Giáo viên kiểm tra rồi bấm phê duyệt")

        con = connect()
        rows = con.execute("""
            SELECT * FROM students
            WHERE status='pending'
            ORDER BY id DESC
        """).fetchall()
        con.close()

        tr = self.tree(
            ("id", "name", "class", "team", "teacher", "parent", "email"),
            ("ID", "Họ tên học sinh", "Lớp", "Tổ",
             "Giáo viên chủ nhiệm", "Phụ huynh", "Email"),
            [55, 190, 80, 70, 190, 170, 260]
        )
        for r in rows:
            tr.insert("", "end", values=(
                r["id"], r["name"], r["class_name"], r["team"],
                r["homeroom_teacher"], r["parent_name"], r["parent_email"]
            ))

        def delete_selected():
            sel = tr.selection()
            if not sel:
                messagebox.showwarning("Chọn", "Hãy chọn học sinh cần xóa.")
                return
            student_id = int(tr.item(sel[0])["values"][0])
            student_name = tr.item(sel[0])["values"][1]

            if not messagebox.askyesno(
                "⚠ XÓA CẢ HỌC SINH + PHỤ HUYNH",
                f'Xóa "{student_name}" cùng tài khoản học sinh, phụ huynh và yêu cầu liên quan?'
            ):
                return

            con2 = connect()
            try:
                # Lấy parent requests liên quan theo học sinh/lớp.
                st = con2.execute(
                    "SELECT name,class_name FROM students WHERE id=?",
                    (student_id,)
                ).fetchone()

                # Xóa dữ liệu liên quan, không để tài khoản mồ côi.
                for table in ("parents", "class_officers", "scores", "task_completions"):
                    try:
                        con2.execute(f"DELETE FROM {table} WHERE student_id=?", (student_id,))
                    except sqlite3.OperationalError:
                        pass

                if st:
                    try:
                        con2.execute(
                            "DELETE FROM parent_requests WHERE student_name=? AND class_name=?",
                            (st["name"], st["class_name"])
                        )
                    except sqlite3.OperationalError:
                        pass

                con2.execute("DELETE FROM students WHERE id=?", (student_id,))
                con2.commit()
                messagebox.showinfo(
                    "Đã xóa",
                    f'Đã xóa "{student_name}" và các tài khoản/dữ liệu liên quan.'
                )
            except Exception as exc:
                con2.rollback()
                messagebox.showerror("Lỗi xóa", f"Không thể xóa hồ sơ:\n{exc}")
            finally:
                con2.close()

            self.pending_students()

        def approve():
            sel = tr.selection()
            if not sel:
                messagebox.showwarning("Chọn", "Hãy chọn một học sinh.")
                return

            student_id = int(tr.item(sel[0])["values"][0])
            code = make_code()
            con2 = connect()
            try:
                student = con2.execute(
                    "SELECT * FROM students WHERE id=?", (student_id,)
                ).fetchone()

                if not student:
                    raise ValueError("Không tìm thấy hồ sơ học sinh.")

                if not student["student_username"] or not student["student_password_hash"]:
                    con2.close()
                    messagebox.showerror(
                        "Thiếu tài khoản",
                        "Hồ sơ này chưa có tên đăng nhập/mật khẩu học sinh.\n"
                        "Học sinh phải đăng ký đủ tài khoản và mật khẩu trước khi được duyệt."
                    )
                    return

                req = con2.execute("""
                    SELECT * FROM parent_requests
                    WHERE student_name=? AND class_name=? AND status='pending'
                    ORDER BY id DESC LIMIT 1
                """, (student["name"], student["class_name"])).fetchone()

                parent_username = (req["parent_username"] if req and req["parent_username"] else "")
                parent_pw_hash = (req["parent_password_hash"] if req and req["parent_password_hash"] else "")
                parent_pw_display = (req["parent_password_display"] if req and req["parent_password_display"] else "")

                # Chỉ duyệt học sinh tại màn hình này; không tự tạo tài khoản phụ huynh thiếu thông tin.
                con2.execute("""
                    UPDATE students
                    SET status='approved', access_code=?, approved_at=?
                    WHERE id=?
                """, (code, now(), student_id))

                if parent_username and parent_pw_hash:
                    con2.execute("""
                        INSERT OR REPLACE INTO parents(
                            student_id,email,username,password_hash,password_display,must_change,verified
                        ) VALUES(?,?,?,?,?,?,0)
                    """, (
                        student_id, student["parent_email"], parent_username,
                        parent_pw_hash, parent_pw_display, 0
                    ))

                con2.commit()
                updated_student = con2.execute(
                    "SELECT * FROM students WHERE id=?", (student_id,)
                ).fetchone()
                con2.close()

                # parent_pw_display có thể rỗng nếu PH chưa đăng ký; không dùng biến chưa tồn tại.
                self.show_approval_result(
                    dict(updated_student), code, parent_pw_display
                )
                self.pending_students()

            except Exception as exc:
                try:
                    con2.rollback()
                except Exception:
                    pass
                try:
                    con2.close()
                except Exception:
                    pass
                messagebox.showerror("Không thể duyệt", f"Không thể duyệt hồ sơ:\n{exc}")

        # Khu vực nút riêng ở đáy, nút có 2 dòng để không bị cắt chữ trên màn hình nhỏ.
        actions = tk.Frame(self, bg=COLORS["bg"])
        actions.pack(side="bottom", fill="x", padx=20, pady=(4, 10))

        approve_btn = tk.Button(
            actions,
            text="✅ PHÊ DUYỆT + TẠO MÃ\nXÁC NHẬN (CHỈ HIỆN CHO GV)",
            command=approve,
            bg=COLORS["green"], fg="white",
            activebackground="#1e9c75", activeforeground="white",
            font=("Arial", 10, "bold"),
            relief="flat", bd=0, cursor="hand2",
            width=32, height=2, wraplength=300,
            padx=8, pady=5
        )
        approve_btn.pack(side="left", padx=6)

        delete_btn = tk.Button(
            actions,
            text="🗑 XÓA CẢ HS + PH",
            command=delete_selected,
            bg=COLORS["red"], fg="white",
            activebackground="#c93443", activeforeground="white",
            font=("Arial", 10, "bold"),
            relief="flat", bd=0, cursor="hand2",
            width=22, height=2, wraplength=220,
            padx=8, pady=5
        )
        delete_btn.pack(side="left", padx=6)

        back_btn = tk.Button(
            actions,
            text="↩ Quay lại",
            command=self.teacher_dashboard,
            bg="#7f8c8d", fg="white",
            activebackground="#687576", activeforeground="white",
            font=("Arial", 10, "bold"),
            relief="flat", bd=0, cursor="hand2",
            width=14, height=2, padx=8, pady=5
        )
        back_btn.pack(side="right", padx=6)

        # Cho phép Enter/double-click trên dòng để duyệt, không phụ thuộc vào nút.
        tr.bind("<Double-1>", lambda e: approve())
        tr.bind("<Return>", lambda e: approve())

    def show_approval_result(self, student, code, parent_temp):
        # Cửa sổ này chỉ được gọi từ tài khoản giáo viên.
        # Không đưa mã vào student_home, parent_home hoặc hồ sơ học sinh.
        win=tk.Toplevel(self)
        win.title("Mã xác nhận - CHỈ HIỂN THỊ CHO GIÁO VIÊN")
        win.geometry("700x650")
        win.configure(bg="white")

        tk.Label(win,text="✅ ĐÃ PHÊ DUYỆT HỌC SINH",
                 bg="white",fg="#17854a",font=("Arial",20,"bold")).pack(pady=(18,8))
        tk.Label(win,
                 text=f"Học sinh: {student['name']}  •  Lớp: {student['class_name']}  •  Tổ: {student['team']}\n"
                      f"Giáo viên chủ nhiệm: {student['homeroom_teacher']}",
                 bg="white",font=("Arial",11),justify="center").pack(pady=6)

        box=tk.Frame(win,bg="#f6f9ff",bd=1,relief="solid")
        box.pack(fill="x",padx=35,pady=16)

        tk.Label(box,text="MÃ XÁC NHẬN HỌC SINH",
                 bg="#f6f9ff",fg="#555",font=("Arial",10,"bold")).pack(pady=(14,2))
        code_lab=tk.Label(box,text=code,bg="#f6f9ff",fg="#bd2727",font=("Arial",34,"bold"))
        code_lab.pack(pady=(0,12))

        tk.Label(box,text="MÃ GIÁO VIÊN",
                 bg="#f6f9ff",fg="#555",font=("Arial",10,"bold")).pack(pady=(4,2))
        tk.Label(box,text=get_teacher_code(),bg="#f6f9ff",fg="#173f7a",font=("Arial",24,"bold")).pack(pady=(0,12))

        tk.Label(win,
                 text="⚠ CHỈ GIÁO VIÊN ĐƯỢC XEM MÃ Ở MÀN HÌNH NÀY.\n"
                      "Giáo viên tự gửi mã cho học sinh/phụ huynh bằng cách phù hợp.\n"
                      "Hệ thống không hiển thị mã trong tài khoản học sinh.",
                 bg="#fff8e8",fg="#7a4b00",font=("Arial",10,"bold"),justify="center",
                 bd=1,relief="solid").pack(fill="x",padx=35,pady=8,ipady=8)

        def copy_code():
            self.clipboard_clear()
            self.clipboard_append(code)
            self.update()
            messagebox.showinfo("Đã sao chép","Đã sao chép mã xác nhận học sinh.")

        def copy_both():
            payload=f"Mã giáo viên: {get_teacher_code()}\nMã xác nhận học sinh: {code}"
            self.clipboard_clear()
            self.clipboard_append(payload)
            self.update()
            messagebox.showinfo("Đã sao chép","Đã sao chép cả mã giáo viên và mã xác nhận.")

        btn=tk.Frame(win,bg="white"); btn.pack(pady=10)
        self.button(btn,"📋 SAO CHÉP MÃ HỌC SINH",copy_code,24,COLORS["blue"]).pack(side="left",padx=5)
        self.button(btn,"📋 SAO CHÉP CẢ 2 MÃ",copy_both,20,COLORS["purple"]).pack(side="left",padx=5)

        if QR_OK:
            payload=(
                "XAC_NHAN_PHU_HUYNH\\n"
                f"Ma giao vien: {get_teacher_code()}\\n"
                f"Ma xac nhan: {code}\\n"
                f"Mat khau phu huynh: {parent_temp}\\n"
                "Chi dung thong tin nay de dang nhap tai khoan phu huynh."
            )
            image=qrcode.make(payload)
            qr_file=os.path.join(BASE_DIR,f"QR_phu_huynh_{student['id']}.png")
            image.save(qr_file)
            try:
                from PIL import ImageTk
                photo=ImageTk.PhotoImage(image.resize((250,250)))
                qr_lab=tk.Label(win,image=photo,bg="white")
                qr_lab.image=photo
                qr_lab.pack(pady=5)
            except Exception:
                pass
            tk.Label(win,text="📱 QR CHỈ HIỂN THỊ CHO GIÁO VIÊN — GỬI QR CHO HỌC SINH/PHỤ HUYNH",
                     bg="white",fg="#173f7a",font=("Arial",10,"bold")).pack(pady=4)
            tk.Label(win,text=f"QR đã lưu: {qr_file}",
                     bg="white",fg="#666",font=("Arial",9)).pack(pady=2)
            tk.Label(win,text="Phụ huynh quét bằng điện thoại → kết quả quét mới hiện mật khẩu phụ huynh.",
                     bg="#fff8e8",fg="#7a4b00",font=("Arial",9,"bold")).pack(pady=4,ipady=5,fill="x",padx=35)
        else:
            tk.Label(win,text="QR chưa tạo vì máy chưa có thư viện qrcode.",
                     bg="white",fg="#9a5b00").pack(pady=6)

        def copy_qr_path():
            self.clipboard_clear()
            self.clipboard_append(qr_file if 'qr_file' in locals() else "")
            self.update()
            messagebox.showinfo("QR", "Đã sao chép đường dẫn tệp QR. Giáo viên có thể gửi tệp QR cho học sinh/phụ huynh.")
        if QR_OK:
            self.button(win,"📋 SAO CHÉP ĐƯỜNG DẪN QR",copy_qr_path,20,COLORS["blue"]).pack(pady=5)
        self.button(win,"Đóng",win.destroy,14,"#7f8c8d").pack(pady=10)

    # -------------------- STUDENT LIST --------------------
    def manage_students(self):
        self.clear()
        self.header("👨‍🎓 DANH SÁCH HỌC SINH")

        con = connect()
        rows = con.execute("""
            SELECT * FROM students
            ORDER BY class_name, team, name
        """).fetchall()
        con.close()

        tr = self.tree(
            ("id", "name", "class", "team", "group", "teacher", "parent", "email", "username", "status"),
            ("ID", "Họ tên học sinh", "Lớp", "Tổ", "Tên nhóm",
             "Giáo viên chủ nhiệm", "Phụ huynh", "Email", "TK học sinh", "Trạng thái"),
            [50, 180, 80, 70, 120, 180, 160, 220, 110, 110]
        )
        status_text = {
            "pending": "Chờ duyệt",
            "approved": "Đã duyệt",
            "verified": "Đã xác nhận",
        }

        for r in rows:
            tr.insert("", "end", values=(
                r["id"], r["name"], r["class_name"], r["team"], r["group_name"] or "",
                r["homeroom_teacher"], r["parent_name"], r["parent_email"],
                r["student_username"] or f"hs{int(r['id']):04d}", status_text.get(r["status"], r["status"])
            ))

        panel=tk.Frame(self,bg=COLORS["bg"]); panel.pack(pady=4)
        self.button(panel,"📥 Tải Excel",self.import_students_excel,16,COLORS["blue"]).pack(side="left",padx=4)
        self.button(panel,"📤 Xuất Excel đầy đủ",self.export_students_excel,20,COLORS["green"]).pack(side="left",padx=4)
        self.button(panel,"🔄 Chuyển lớp / chuyển tổ",lambda:self.transfer_student(tr),22,COLORS["orange"]).pack(side="left",padx=5)
        self.button(panel,"🔐 Xem tài khoản + mật khẩu",lambda:self.show_student_credentials(tr),25,COLORS["purple"]).pack(side="left",padx=5)
        self.button(self,"🗑 Xóa học sinh đã chọn",lambda:self.delete_one_student(tr),24,COLORS["red"]).pack(pady=4)

        self.button(
            self, "Quay lại", self.teacher_dashboard, 15, "#7f8c8d"
        ).pack(pady=5)

    def show_student_credentials(self, tree):
        sel=tree.selection()
        if not sel:return
        sid=int(tree.item(sel[0])["values"][0]); con=connect(); st=con.execute("SELECT * FROM students WHERE id=?",(sid,)).fetchone(); p=con.execute("SELECT * FROM parents WHERE student_id=?",(sid,)).fetchone(); con.close()
        if st: messagebox.showinfo("Thông tin tài khoản",f"Học sinh: {st['name']}\nLớp: {st['class_name']}\nTổ: {st['team']}\n\nTài khoản học sinh: {st['student_username']}\nMật khẩu học sinh: {st['student_password_display']}\n\nTên đăng nhập phụ huynh: {(p['username'] if p and p['username'] else (p['email'] if p else st['parent_email']))}\nMật khẩu phụ huynh: {(p['password_display'] if p and p['password_display'] else 'Chưa có mật khẩu được lưu')}")

    def transfer_student(self, tree):
        sel=tree.selection()
        if not sel:return
        sid=int(tree.item(sel[0])["values"][0]); con=connect(); st=con.execute("SELECT * FROM students WHERE id=?",(sid,)).fetchone(); con.close()
        if not st:return
        nc=simpledialog.askstring("Chuyển lớp","Nhập lớp mới:",initialvalue=st["class_name"]);
        if nc is None:return
        nt=simpledialog.askstring("Chuyển tổ",f"Học sinh: {st['name']}\nNhập tổ mới:",initialvalue=st["team"]);
        if nt is None:return
        nc=nc.strip(); nt=nt.strip();
        if not nc or not nt:return
        con=connect(); c=con.execute("SELECT homeroom_teacher FROM classes WHERE class_name=?",(nc,)).fetchone(); teacher=c["homeroom_teacher"] if c else st["homeroom_teacher"]
        notice=f"Bạn đã được chuyển từ lớp {st['class_name']} - Tổ {st['team']} sang lớp {nc} - Tổ {nt}. Tất cả điểm, nhiệm vụ, thành tích và hồ sơ được giữ nguyên."
        con.execute("UPDATE students SET class_name=?,team=?,homeroom_teacher=?,transfer_notice=? WHERE id=?",(nc,nt,teacher,notice,sid)); con.commit(); con.close(); messagebox.showinfo("Đã chuyển",notice); self.manage_students()

    def delete_one_student(self, tree):
        sel = tree.selection()
        if not sel:
            messagebox.showwarning("Chọn", "Hãy chọn học sinh cần xóa.")
            return

        values = tree.item(sel[0])["values"]
        student_id = values[0]
        student_name = values[1]

        password = simpledialog.askstring(
            "🔐 Xác nhận xóa",
            "Nhập mật khẩu giáo viên:",
            show="*"
        )
        if password is None:
            return

        con = connect()
        row = con.execute(
            "SELECT password_hash FROM teacher WHERE id=1"
        ).fetchone()

        if not row or row["password_hash"] != hash_pw(password):
            con.close()
            messagebox.showerror("Từ chối", "Mật khẩu giáo viên không đúng.")
            return

        ok = messagebox.askyesno(
            "Xóa toàn bộ dữ liệu học sinh",
            f'Xóa "{student_name}" và toàn bộ dữ liệu phụ huynh, điểm, nhiệm vụ, mã xác nhận?'
        )
        if not ok:
            con.close()
            return

        con.execute("DELETE FROM students WHERE id=?", (student_id,))
        con.commit()
        con.close()
        messagebox.showinfo("Đã xóa", "Đã xóa hoàn toàn dữ liệu học sinh.")
        self.manage_students()

    # -------------------- SELECT STUDENT --------------------
    def choose_student(self):
        con = connect()
        rows = con.execute("""
            SELECT id,name,class_name,team,homeroom_teacher,status
            FROM students
            ORDER BY class_name,team,name
        """).fetchall()
        con.close()

        if not rows:
            messagebox.showinfo("Chưa có", "Chưa có học sinh được duyệt.")
            return None

        win = tk.Toplevel(self)
        win.title("Chọn học sinh")
        win.geometry("760x480")

        tr = ttk.Treeview(
            win,
            columns=("id", "name", "class", "team", "teacher"),
            show="headings"
        )
        for c, h, w in [
            ("id", "ID", 50),
            ("name", "Họ tên học sinh", 230),
            ("class", "Lớp", 80),
            ("team", "Tổ", 80),
            ("teacher", "Giáo viên chủ nhiệm", 200),
            ("status", "Trạng thái", 110),
        ]:
            tr.heading(c, text=h)
            tr.column(c, width=w)

        for r in rows:
            tr.insert("", "end", values=(
                r["id"], r["name"], r["class_name"],
                r["team"], r["homeroom_teacher"], r["status"]
            ))
        tr.pack(fill="both", expand=True, padx=10, pady=10)

        result = {"id": None}

        def choose():
            sel = tr.selection()
            if sel:
                result["id"] = tr.item(sel[0])["values"][0]
                win.destroy()

        self.button(win, "CHỌN", choose, 15, COLORS["blue"]).pack(pady=10)
        win.grab_set()
        self.wait_window(win)
        return result["id"]

    # -------------------- SCORE --------------------
    def score_manager(self):
        self.clear()
        self.header("⭐ ĐIỂM CỘNG / TRỪ", "Chọn học sinh, thông tin lớp và tổ tự hiện")

        card = tk.Frame(self, bg="white", bd=1, relief="solid")
        card.pack(pady=12, ipadx=35, ipady=20)

        self.selected_student_id = None
        selected = tk.StringVar(value="Chưa chọn học sinh")
        criterion = tk.StringVar(value="Đi học đúng giờ")
        points = tk.StringVar(value="1")
        note = tk.StringVar()

        self.button(
            card, "👤 Chọn học sinh",
            lambda: self.pick_student_label(selected),
            20, COLORS["blue"]
        ).grid(row=0, column=0, columnspan=2, pady=7)

        tk.Label(
            card, textvariable=selected, bg="white",
            fg="#3155a6", font=("Arial", 12, "bold")
        ).grid(row=1, column=0, columnspan=2, pady=8)

        for row, label, var in [
            (2, "Tiêu chí", criterion),
            (3, "Điểm (+ / -)", points),
            (4, "Ghi chú", note),
        ]:
            tk.Label(card, text=label + ":", bg="white").grid(
                row=row, column=0, sticky="e", padx=8, pady=7
            )
            tk.Entry(card, textvariable=var, width=38).grid(
                row=row, column=1, padx=8, pady=7
            )

        self.button(
            card, "💾 LƯU ĐIỂM",
            lambda: self.save_score(criterion, points, note),
            20, COLORS["purple"]
        ).grid(row=5, column=0, columnspan=2, pady=13)

        tk.Label(
            self,
            text="Ví dụ: Bài kiểm tra +8 • Đi học đúng giờ +1 • Làm vệ sinh +2 • Vi phạm -3",
            bg=COLORS["bg"], fg=COLORS["gray"]
        ).pack(pady=8)

        self.button(
            self, "Quay lại", self.teacher_dashboard, 15, "#7f8c8d"
        ).pack()

    def pick_student_label(self, variable):
        sid = self.choose_student()
        if sid is None:
            return
        self.selected_student_id = sid
        con = connect()
        r = con.execute(
            "SELECT name,class_name,team,homeroom_teacher FROM students WHERE id=?",
            (sid,)
        ).fetchone()
        con.close()
        variable.set(
            f"{r['name']} • {r['class_name']} • {r['team']} • {r['homeroom_teacher']}"
        )

    def save_score(self, criterion, points, note):
        if not self.selected_student_id:
            messagebox.showwarning("Thiếu", "Hãy chọn học sinh.")
            return
        if not criterion.get().strip():
            messagebox.showwarning("Thiếu", "Hãy nhập tiêu chí.")
            return
        try:
            value = int(points.get())
        except ValueError:
            messagebox.showerror("Lỗi", "Điểm phải là số nguyên.")
            return

        con = connect()
        con.execute("""
            INSERT INTO scores(student_id,criterion,points,note,created_at)
            VALUES(?,?,?,?,?)
        """, (
            self.selected_student_id, criterion.get().strip(),
            value, note.get().strip(), now()
        ))
        con.commit()
        con.close()
        messagebox.showinfo("Đã lưu", "Đã cập nhật điểm.")

