    def save_task(self, task, status, points, note):
        if not self.selected_student_id:
            messagebox.showwarning("Thiếu", "Hãy chọn học sinh.")
            return
        try:
            value = int(points.get())
        except ValueError:
            messagebox.showerror("Lỗi", "Điểm phải là số nguyên.")
            return

        con = connect()
        con.execute("""
            INSERT INTO tasks(
                student_id,task_date,task,status,points,note
            ) VALUES(?,?,?,?,?,?)
        """, (
            self.selected_student_id,
            datetime.now().strftime("%d/%m/%Y"),
            task.get().strip(), status.get(), value, note.get().strip()
        ))
        con.commit()
        con.close()
        messagebox.showinfo("Đã lưu", "Đã lưu phân công nhiệm vụ.")

    # -------------------- BAN CAN SU --------------------
    def manage_officers(self):
        self.clear(); self.header("🧑‍💼 BAN CÁN SỰ LỚP", "Chọn học sinh → nhập chức vụ và quyền xem dữ liệu tổ")
        con=connect(); rows=con.execute("SELECT s.id,s.name,s.class_name,s.team,COALESCE(o.role,'') officer_role,COALESCE(o.scope,'Không làm gì cả') officer_scope FROM students s LEFT JOIN class_officers o ON o.student_id=s.id WHERE s.status IN ('approved','verified') ORDER BY s.class_name,s.team,s.name").fetchall(); con.close()
        tr=self.tree(("id","name","class","team","role","scope"),("ID","Họ tên học sinh","Lớp","Tổ","Chức vụ","Quyền tổ"),[55,230,90,70,220,260])
        for r in rows: tr.insert("","end",values=(r["id"],r["name"],r["class_name"],r["team"],r["officer_role"] or "",r["officer_scope"] or "Không làm gì cả"))
        panel=tk.Frame(self,bg=COLORS["bg"]); panel.pack(pady=7)
        def assign():
            sel=tr.selection()
            if not sel: messagebox.showwarning("Chọn","Hãy chọn tên học sinh cần làm ban cán sự."); return
            sid,name=int(tr.item(sel[0])["values"][0]),tr.item(sel[0])["values"][1]
            entered_name=simpledialog.askstring("Tên người này",f"Tên người này (đang chọn: {name}):",initialvalue=name)
            if entered_name is None or not entered_name.strip(): return
            role=simpledialog.askstring("Chức vụ của người này",f"Tên người này: {entered_name.strip()}\n\nNhập chức vụ của người này:")
            if role is None or not role.strip(): return
            scope=simpledialog.askstring("Quyền ban cán sự","Nhập 1, 2 hoặc 3:\n1 - Xem điểm cộng tổ mình và phân công/nhiệm vụ tổ mình\n2 - Xem điểm cộng tất cả các tổ và phân công/nhiệm vụ tất cả các tổ\n3 - Không làm gì cả",initialvalue="1")
            if scope is None:return
            scope={"1":"Tổ mình","2":"Tất cả các tổ","3":"Không làm gì cả"}.get(scope.strip(),"Không làm gì cả")
            con2=connect(); con2.execute("INSERT OR REPLACE INTO class_officers(student_id,role,scope) VALUES(?,?,?)",(sid,role.strip(),scope)); con2.execute("UPDATE students SET name=?,officer_role=?,officer_scope=?,transfer_notice='' WHERE id=?",(entered_name.strip(),role.strip(),scope,sid)); con2.commit(); con2.close(); messagebox.showinfo("Đã cập nhật",f"Tên: {entered_name.strip()}\nChức vụ: {role.strip()}\nQuyền: {scope}"); self.manage_officers()
        def remove():
            sel=tr.selection()
            if not sel:return
            sid,name=int(tr.item(sel[0])["values"][0]),tr.item(sel[0])["values"][1]
            if not messagebox.askyesno("Xóa ban cán sự",f"Xóa chức vụ ban cán sự của {name}?"):return
            con2=connect(); con2.execute("DELETE FROM class_officers WHERE student_id=?",(sid,)); con2.execute("UPDATE students SET officer_role='',officer_scope='Không làm gì cả',transfer_notice=? WHERE id=?",("Thông báo: Chức vụ ban cán sự lớp của bạn đã được giáo viên cập nhật và kết thúc.",sid)); con2.commit(); con2.close(); messagebox.showinfo("Đã xóa",f"Đã xóa ban cán sự của {name}. Học sinh sẽ nhận thông báo khi đăng nhập lại."); self.manage_officers()
        self.button(panel,"✅ Thêm/sửa ban cán sự",assign,22,COLORS["green"]).pack(side="left",padx=5); self.button(panel,"↩ Xóa ban cán sự",remove,18,COLORS["red"]).pack(side="left",padx=5); self.button(self,"Quay lại",self.teacher_dashboard,15,"#7f8c8d").pack(pady=7)

    def officer_view(self):
        self.clear(); self.header("🧑‍💼 BAN CÁN SỰ", "Mọi người đều xem được; chỉ giáo viên mới được sửa")
        con=connect()
        rows=con.execute("""
            SELECT s.name,s.class_name,s.team,COALESCE(o.role,'') role
            FROM students s LEFT JOIN class_officers o ON o.student_id=s.id
            WHERE s.status IN ('approved','verified') AND COALESCE(o.role,'')<>''
            ORDER BY s.class_name,s.team,s.name
        """).fetchall(); con.close()
        tr=self.tree(("name","class","team","role"),("Họ tên học sinh","Lớp","Tổ","Vai trò ban cán sự"),[300,120,100,320])
        for r in rows: tr.insert("", "end",values=(r["name"],r["class_name"],r["team"],r["role"]))
        self.button(self,"Quay lại hồ sơ",self.student_home,15,"#7f8c8d").pack(pady=8)

    # -------------------- SƠ ĐỒ LỚP TƯƠNG TÁC --------------------
    def diagram_view(self, teacher_edit=False):
        self.clear()
        self.header("🗺 SƠ ĐỒ LỚP", "Kéo/thay đổi sơ đồ chỉ dành cho giáo viên; mọi người đều có thể bấm vào từng ô")

        con=connect()
        classes=con.execute("SELECT class_name FROM classes ORDER BY class_name").fetchall()
        if not classes:
            classes=con.execute("SELECT DISTINCT class_name FROM students ORDER BY class_name").fetchall()
        con.close()
        class_names=[r["class_name"] for r in classes]
        if not class_names:
            messagebox.showinfo("Chưa có dữ liệu","Chưa có lớp/học sinh để vẽ sơ đồ.")
            self.show_login() if not teacher_edit else self.teacher_dashboard(); return

        top=tk.Frame(self,bg=COLORS["bg"]); top.pack(fill="x",padx=20)
        selected_class=tk.StringVar(value=class_names[0])
        ttk.Combobox(top,textvariable=selected_class,values=class_names,state="readonly",width=16).pack(side="left",padx=4)
        layout=tk.StringVar(value="grid")
        con=connect(); setting=con.execute("SELECT layout FROM diagram_settings WHERE id=1").fetchone(); con.close()
        if setting: layout.set(setting["layout"])

        tk.Label(top,text="Kiểu sơ đồ:",bg=COLORS["bg"]).pack(side="left",padx=(15,4))
        layout_box=ttk.Combobox(top,textvariable=layout,values=("grid","rows","semicircle"),state="readonly",width=14)
        layout_box.pack(side="left",padx=4)

        canvas=tk.Canvas(self,bg="white",highlightthickness=1,highlightbackground="#cbd5e1")
        canvas.pack(fill="both",expand=True,padx=20,pady=12)
        info=tk.StringVar(value="Bấm vào một học sinh để xem thông tin")
        tk.Label(self,textvariable=info,bg=COLORS["bg"],fg=COLORS["gray"]).pack(pady=3)

        drag={"item":None,"offset":(0,0),"student_id":None}
        node_map={}

        def get_students():
            con=connect(); rows=con.execute("""
                SELECT s.id,s.name,s.class_name,s.team,COALESCE(o.role,'') role
                FROM students s LEFT JOIN class_officers o ON o.student_id=s.id
                WHERE s.class_name=? AND s.status IN ('approved','verified')
                ORDER BY s.team,s.name
            """,(selected_class.get(),)).fetchall(); con.close(); return rows

        def draw():
            canvas.delete("all"); node_map.clear()
            rows=get_students()
            w=max(canvas.winfo_width(),800); h=max(canvas.winfo_height(),520)
            title_y=40
            canvas.create_text(w/2,title_y,text=f"{selected_class.get()} • Giáo viên chủ nhiệm",font=("Arial",18,"bold"),fill="#3155a6")
            canvas.create_rectangle(w/2-90,70,w/2+90,110,fill="#e8eefc",outline="#7b8fcf")
            canvas.create_text(w/2,90,text="BẢNG / GIÁO VIÊN",font=("Arial",10,"bold"),fill="#3155a6")
            if not rows:return
            n=len(rows); r=rows
            positions=[]
            if layout.get()=="rows":
                cols=4; cell_w=180; cell_h=100
                for i in range(n):
                    row=i//cols; col=i%cols
                    positions.append((120+col*cell_w,160+row*cell_h))
            elif layout.get()=="semicircle":
                import math
                cx=w/2; cy=310; rx=max(220,w*0.35); ry=max(120,h*0.28)
                for i in range(n):
                    ang=math.pi*0.1 + (math.pi*0.8*(i/(max(1,n-1))))
                    positions.append((cx-rx*math.cos(ang), cy-ry*math.sin(ang)))
            else:
                cols=max(3,min(6,(w-80)//170));
                for i in range(n):
                    row=i//cols; col=i%cols
                    positions.append((90+col*170,160+row*100))
            for row,(x,y) in zip(r,positions):
                fill="#fff7e6" if row["role"] else "#f7fbff"
                outline="#f39c12" if row["role"] else "#7aa2e8"
                item=canvas.create_rectangle(x,y,x+145,y+72,fill=fill,outline=outline,width=2)
                title=row["name"][:20]
                role_text=f"\n{row['role']}" if row["role"] else ""
                canvas.create_text(x+72,y+22,text=title,font=("Arial",10,"bold"),fill="#263238")
                canvas.create_text(x+72,y+48,text=f"{row['team']} • {row['role']}" if row['role'] else row['team'],font=("Arial",9),fill="#667085")
                node_map[item]=(row,x,y)
                canvas.tag_bind(item,"<Button-1>",lambda e,it=item: click_node(it))
                if teacher_edit:
                    canvas.tag_bind(item,"<B1-Motion>",lambda e,it=item: drag_node(e,it))
                    canvas.tag_bind(item,"<ButtonPress-1>",lambda e,it=item: start_drag(e,it))

        def click_node(item):
            row=node_map[item][0]
            info.set(f"{row['name']}  •  {row['class_name']}  •  {row['team']}  •  {row['role'] or 'Học sinh'}")

        def start_drag(event,item):
            drag["item"]=item; drag["offset"]=(event.x, event.y)
        def drag_node(event,item):
            if not teacher_edit or drag["item"]!=item:return
            row,x,y=node_map[item]; dx=event.x-drag["offset"][0]; dy=event.y-drag["offset"][1]
            canvas.move(item,dx,dy)
            # Move text items belonging to same student is not stored; redraw is used as lightweight editor.
            drag["offset"]=(event.x,event.y)
            info.set("Đang kéo ô học sinh... bấm 'Lưu vị trí' để giữ bố cục trong phiên này.")

        def apply_layout():
            if not teacher_edit:
                return
            con=connect(); con.execute("UPDATE diagram_settings SET layout=? WHERE id=1",(layout.get(),)); con.commit(); con.close(); draw()
        def save_layout():
            if teacher_edit:
                con=connect(); con.execute("UPDATE diagram_settings SET layout=? WHERE id=1",(layout.get(),)); con.commit(); con.close(); messagebox.showinfo("Đã lưu","Đã lưu kiểu sơ đồ cho cả lớp.")
        layout_box.bind("<<ComboboxSelected>>",lambda e: draw())
        ttk.Combobox(top,textvariable=selected_class,values=class_names,state="readonly",width=16).bind if False else None

        if teacher_edit:
            self.button(top,"💾 Lưu kiểu sơ đồ",save_layout,18,COLORS["green"]).pack(side="left",padx=6)
            self.button(top,"↻ Vẽ lại",draw,13,COLORS["orange"]).pack(side="left",padx=4)
        else:
            layout_box.configure(state="disabled")

        # Re-draw when class changes by attaching a fresh binding to the first combobox.
        for widget in top.winfo_children():
            if isinstance(widget, ttk.Combobox) and widget is not layout_box:
                widget.bind("<<ComboboxSelected>>", lambda e: draw())

        self.button(self,"Quay lại hồ sơ",self.teacher_dashboard if teacher_edit else self.student_home,15,"#7f8c8d").pack(pady=6)
        self.after(100,draw)

    # -------------------- RANKING --------------------
    def ranking(self):
        self.clear()
        self.header("🏆 XẾP HẠNG HỌC SINH", "Tổng điểm cộng / trừ")

        con = connect()
        rows = con.execute("""
            SELECT s.name,s.class_name,s.team,
                   COALESCE(SUM(sc.points),0) AS total
            FROM students s
            LEFT JOIN scores sc ON s.id=sc.student_id
            WHERE s.status IN ('approved','verified')
            GROUP BY s.id
            ORDER BY total DESC, s.name ASC
        """).fetchall()
        con.close()

        tr = self.tree(
            ("rank","name","class","team","total"),
            ("Hạng","Họ tên học sinh","Lớp","Tổ","Tổng điểm"),
            [70,320,100,90,140]
        )
        for i, r in enumerate(rows, start=1):
            tr.insert("", "end", values=(
                i, r["name"], r["class_name"], r["team"], r["total"]
            ))

        self.button(
            self, "Quay lại", self.teacher_dashboard, 15, "#7f8c8d"
        ).pack(pady=8)

    # -------------------- ACCOUNT / SECURITY MANAGEMENT --------------------
    def manage_accounts(self):
        self.clear()
        self.header("🔐 TÀI KHOẢN & BẢO MẬT", "Giáo viên xem trạng thái tài khoản và quản lý quyền truy cập")

        con = connect()
        rows = con.execute("""
            SELECT p.student_id, p.email, p.verified, p.must_change,
                   s.name, s.class_name, s.team, s.parent_name, s.status
            FROM parents p JOIN students s ON s.id=p.student_id
            ORDER BY s.class_name, s.name
        """).fetchall()
        con.close()

        tr = self.tree(
            ("sid","student","class","team","parent","email","verified","must_change"),
            ("ID HS","Học sinh","Lớp","Tổ","Phụ huynh","Email tài khoản PH","Xác nhận","Đổi MK lần đầu"),
            [70,200,90,70,180,280,100,120]
        )
        for r in rows:
            tr.insert("", "end", values=(
                r["student_id"], r["name"], r["class_name"], r["team"],
                r["parent_name"], r["email"],
                "Đã xác nhận" if r["verified"] else "Chưa xác nhận",
                "Có" if r["must_change"] else "Không"
            ))

        panel = tk.Frame(self, bg=COLORS["bg"])
        panel.pack(pady=8)

        def reset_parent():
            sel = tr.selection()
            if not sel:
                messagebox.showwarning("Chọn", "Hãy chọn tài khoản phụ huynh.")
                return
            sid = tr.item(sel[0])["values"][0]
            teacher_pw = simpledialog.askstring("Xác nhận giáo viên", "Nhập mật khẩu giáo viên:", show="*")
            if teacher_pw is None:
                return
            con2 = connect()
            row = con2.execute("SELECT password_hash FROM teacher WHERE id=1").fetchone()
            if not row or row["password_hash"] != hash_pw(teacher_pw):
                con2.close()
                messagebox.showerror("Từ chối", "Mật khẩu giáo viên không đúng.")
                return
            temp = make_parent_temp()
            con2.execute("UPDATE parents SET password_hash=?, password_display=?, must_change=1 WHERE student_id=?", (hash_pw(temp), temp, sid))
            con2.commit(); con2.close()
            messagebox.showinfo("Đã cấp lại", f"Mật khẩu phụ huynh mới do giáo viên cấp:\n{temp}\n\nĐây không phải mật khẩu email.")
            self.manage_accounts()

        def delete_parent():
            sel = tr.selection()
            if not sel:
                messagebox.showwarning("Chọn", "Hãy chọn phụ huynh.")
                return
            sid = tr.item(sel[0])["values"][0]
            teacher_pw = simpledialog.askstring("Xóa phụ huynh", "Nhập mật khẩu giáo viên:", show="*")
            if teacher_pw is None:
                return
            con2 = connect()
            row = con2.execute("SELECT password_hash FROM teacher WHERE id=1").fetchone()
            if not row or row["password_hash"] != hash_pw(teacher_pw):
                con2.close(); messagebox.showerror("Từ chối", "Mật khẩu giáo viên không đúng."); return
            ok = messagebox.askyesno("Xóa tài khoản phụ huynh", "Xóa tài khoản phụ huynh khỏi hệ thống? Hồ sơ học sinh vẫn giữ nguyên.")
            if ok:
                con2.execute("DELETE FROM parents WHERE student_id=?", (sid,))
                con2.commit()
            con2.close()
            if ok: self.manage_accounts()

        tk.Label(panel, text="Lưu ý: vì lý do bảo mật, mật khẩu thật không hiển thị. Giáo viên có thể cấp lại mật khẩu.", bg=COLORS["bg"], fg=COLORS["gray"]).pack(side="left", padx=8)
        self.button(panel, "🔁 Cấp lại MK PH", reset_parent, 16, COLORS["purple"]).pack(side="left", padx=4)
        self.button(panel, "🗑 Xóa PH", delete_parent, 13, COLORS["red"]).pack(side="left", padx=4)
        self.button(self, "Quay lại", self.teacher_dashboard, 15, "#7f8c8d").pack(pady=8)

    # -------------------- DELETE ALL --------------------
    def delete_all_data(self):
        pwd = simpledialog.askstring(
            "🔐 XÓA TOÀN BỘ DỮ LIỆU",
            "Nhập mật khẩu giáo viên để tiếp tục:",
            show="*"
        )
        if pwd is None:
            return

        con = connect()
        row = con.execute(
            "SELECT password_hash FROM teacher WHERE id=1"
        ).fetchone()
        if not row or row["password_hash"] != hash_pw(pwd):
            con.close()
            messagebox.showerror("Từ chối", "Mật khẩu giáo viên không đúng.")
            return

        confirm = messagebox.askyesno(
            "⚠ XÁC NHẬN LẦN CUỐI",
            "Xóa TẤT CẢ học sinh, phụ huynh, điểm, nhiệm vụ và lớp?\n\n"
            "Dữ liệu đã xóa sẽ không thể đăng nhập hoặc khôi phục từ ứng dụng này."
        )
        if not confirm:
            con.close()
            return

        con.execute("DELETE FROM parents")
        con.execute("DELETE FROM scores")
        con.execute("DELETE FROM tasks")
        con.execute("DELETE FROM students")
        con.execute("DELETE FROM classes")
        con.commit()
        con.close()

        messagebox.showinfo(
            "Đã xóa",
            "Đã xóa toàn bộ dữ liệu. Dữ liệu/tài khoản phụ huynh cũ không còn truy cập được."
        )
        self.teacher_dashboard()

    # -------------------- PARENT LOGIN --------------------
    def parent_login(self):
        self.clear()
        self.header(
            "👨‍👩‍👧 PHỤ HUYNH",
            "Đăng nhập bằng tên đăng nhập và mật khẩu do chính phụ huynh tạo"
        )

        card=tk.Frame(self,bg="white",bd=1,relief="solid")
        card.pack(pady=28,ipadx=35,ipady=25)

        username=tk.Entry(card,width=40)
        password=tk.Entry(card,width=40,show="*")

        tk.Label(card,text="Tên đăng nhập",bg="white").grid(row=0,column=0,padx=8,pady=9)
        username.grid(row=0,column=1,padx=8,pady=9)
        tk.Label(card,text="Mật khẩu",bg="white").grid(row=1,column=0,padx=8,pady=9)
        password.grid(row=1,column=1,padx=8,pady=9)

        def login():
            u=username.get().strip()
            pw=password.get()
            if not u or not pw:
                messagebox.showwarning("Thiếu thông tin","Hãy nhập tên đăng nhập và mật khẩu.")
                return
            con=connect()
            row=con.execute("""
                SELECT
                    s.id AS student_id,
                    s.name AS student_name,
                    s.class_name,
                    s.team,
                    s.homeroom_teacher,
                    s.parent_name,
                    s.parent_email,
                    s.status AS student_status,
                    p.email AS parent_email_login,
                    p.username AS parent_username,
                    p.password_display AS parent_password_display,
                    p.password_hash,
                    s.student_username, s.student_password_display,
                    s.officer_role, s.officer_scope, s.transfer_notice,
                    p.must_change,
                    p.verified
                FROM parents p
                JOIN students s ON s.id=p.student_id
                WHERE lower(p.username)=lower(?) AND p.password_hash=?
                  AND p.verified IN (0,1) AND s.status IN ('approved','verified')
            """,(u,hash_pw(pw))).fetchone()
            con.close()

            if not row:
                messagebox.showerror(
                    "Đăng nhập",
                    "Tên đăng nhập hoặc mật khẩu sai, hoặc phụ huynh chưa được giáo viên xác nhận."
                )
                return

            self.current_student=dict(row)
            def after_profile():
                if row["must_change"]:
                    self.change_parent_password()
                else:
                    self.student_home()
            if (not (row["team"] or "").strip()) or (not (row["parent_email"] or "").strip()):
                self.complete_first_login_profile(dict(row), after_profile)
            elif row["must_change"]:
                self.change_parent_password()
            else:
                self.student_home()

        self.button(card,"🔓 ĐĂNG NHẬP",login,20,COLORS["pink"]).grid(
            row=2,column=0,columnspan=2,pady=14
        )
        self.button(self,"Quay lại",self.show_login,15,"#7f8c8d").pack()

    def change_parent_password(self):
        new = simpledialog.askstring(
            "Đổi mật khẩu phụ huynh",
            "Mật khẩu mới (ít nhất 6 ký tự):",
            show="*"
        )
        if not new or len(new) < 6:
            messagebox.showwarning("Lưu ý", "Mật khẩu phải có ít nhất 6 ký tự.")
            return

        student_id = self.current_student["student_id"]

        con = connect()
        con.execute("""
            UPDATE parents
            SET password_hash=?, must_change=0
            WHERE student_id=?
        """, (hash_pw(new), student_id))
        con.commit()
        con.close()

        messagebox.showinfo("Thành công", "Đã đổi mật khẩu phụ huynh.")
        self.student_home()

    # -------------------- XÁC NHẬN BẰNG MÃ --------------------
    def _code_form(self, title, subtitle, success_kind):
        self.clear()
        self.header(title, subtitle)
        card=tk.Frame(self,bg="white",bd=1,relief="solid")
        card.pack(pady=30,ipadx=45,ipady=30)

        tk.Label(card,text="Mã giáo viên và mã xác nhận đều do giáo viên cấp.",
                 bg="white",fg=COLORS["gray"],justify="center").pack(pady=(0,10))
        tk.Label(card,text="MÃ GIÁO VIÊN",bg="white",font=("Arial",10,"bold")).pack(pady=(8,2))
        teacher_entry=tk.Entry(card,width=20,font=("Arial",20),justify="center")
        teacher_entry.pack(pady=6)
        tk.Label(card,text="MÃ XÁC NHẬN HỌC SINH",bg="white",font=("Arial",10,"bold")).pack(pady=(8,2))
        code_entry=tk.Entry(card,width=20,font=("Arial",20),justify="center")
        code_entry.pack(pady=6)

        def verify():
            teacher_code=teacher_entry.get().strip().upper()
            code=code_entry.get().strip()
            if not teacher_code:
                messagebox.showwarning("Mã giáo viên","Hãy nhập mã giáo viên do giáo viên cung cấp.")
                return
            if len(code)!=6 or not code.isdigit():
                messagebox.showwarning("Mã xác nhận","Mã xác nhận phải gồm đúng 6 chữ số.")
                return
            if teacher_code != get_teacher_code():
                messagebox.showerror("Không hợp lệ","Mã giáo viên không đúng.")
                return

            con=connect()
            row=con.execute(
                "SELECT * FROM students WHERE access_code=? AND status IN ('approved','verified')",
                (code,)
            ).fetchone()
            if not row:
                con.close()
                messagebox.showerror("Không hợp lệ","Mã xác nhận sai hoặc học sinh chưa được giáo viên phê duyệt.")
                return

            if success_kind=="student":
                # Chỉ xác nhận tài khoản học sinh; tuyệt đối không bật verified của phụ huynh.
                con.execute("UPDATE students SET status='verified',verified_at=? WHERE id=?",(now(),row["id"]))
                con.commit()
                student_row=con.execute("SELECT * FROM students WHERE id=?",(row["id"],)).fetchone()
                con.close()
                self.current_student=dict(student_row)
                messagebox.showinfo("Xác nhận thành công",
                                    f"Học sinh {row['name']} đã được xác nhận bằng mã giáo viên cấp.")
                self.student_home()
            else:
                # Chỉ phụ huynh mới được đánh dấu verified.
                parent=con.execute("SELECT student_id FROM parents WHERE student_id=?",(row["id"],)).fetchone()
                if not parent:
                    con.close()
                    messagebox.showerror("Chưa có tài khoản","Giáo viên chưa tạo tài khoản phụ huynh cho học sinh này.")
                    return
                con.execute("UPDATE parents SET verified=1 WHERE student_id=?",(row["id"],))
                con.commit()
                con.close()
                messagebox.showinfo(
                    "Xác nhận phụ huynh thành công",
                    f"Phụ huynh của {row['name']} đã được xác nhận.\n\n"
                    "Bây giờ phụ huynh dùng mật khẩu do giáo viên cấp để đăng nhập."
                )
                self.parent_login()

        button_text = "🎓 XÁC NHẬN HỌC SINH" if success_kind=="student" else "👨‍👩‍👧 XÁC NHẬN PHỤ HUYNH"
        self.button(card,button_text,verify,28,COLORS["purple"]).pack(pady=14)
        self.button(self,"Quay lại",self.show_login,14,"#7f8c8d").pack(pady=4)

    def student_verify_code(self):
        self._code_form(
            "🔑 XÁC NHẬN HỌC SINH BẰNG MÃ",
            "Nhập MÃ GIÁO VIÊN + MÃ XÁC NHẬN HỌC SINH do giáo viên gửi",
            "student"
        )

    def parent_verify_code(self):
        self._code_form(
            "🔑 XÁC NHẬN PHỤ HUYNH BẰNG MÃ / QR",
            "Nhập MÃ GIÁO VIÊN + MÃ XÁC NHẬN HỌC SINH do giáo viên cấp",
            "parent"
        )

    # Giữ tên cũ để các luồng V12 cũ không bị lỗi khi gọi.
    def verify_code(self):
        self.parent_verify_code()

    # -------------------- STUDENT/PARENT HOME --------------------
    def student_home(self):
        self.clear()
        self.configure(bg=COLORS["bg"])
        s = self.current_student or {}

        name = s.get("student_name", s.get("name", "Học sinh"))
        class_name = s.get("class_name", "")
        team = s.get("team", "")
        teacher = s.get("homeroom_teacher", "")
        parent = s.get("parent_name", "")

        sid = s.get("student_id", s.get("id"))
        con = connect()
        scores = con.execute("""
            SELECT criterion, points, note, created_at
            FROM scores WHERE student_id=? ORDER BY id DESC
        """, (sid,)).fetchall()
        tasks = con.execute("""
            SELECT task_date, task, status, points, note
            FROM tasks WHERE student_id=? ORDER BY id DESC
        """, (sid,)).fetchall()
        total = con.execute("""
            SELECT COALESCE(SUM(points),0) total
            FROM scores WHERE student_id=?
        """, (sid,)).fetchone()["total"]
        con.close()

        shell = tk.Frame(self, bg=COLORS["bg"])
        shell.pack(fill="both", expand=True)
        top = tk.Frame(shell, bg="white", bd=1, relief="solid")
        top.pack(fill="x", padx=18, pady=14)

        tk.Label(top, text="🌟", bg="white", fg=COLORS["blue"],
                 font=("Arial", 26)).pack(side="left", padx=14)
        intro = tk.Frame(top, bg="white")
        intro.pack(side="left", fill="x", expand=True)
        role = "PHỤ HUYNH" if s.get("parent_email_login") else ("BAN CÁN SỰ LỚP" if s.get("login_role")=="officer" or s.get("officer_role") else "HỌC SINH")
        tk.Label(intro, text=f"Xin chào, {name}", bg="white",
                 fg=COLORS["navy"], font=("Arial", 18, "bold")).pack(anchor="w")
        tk.Label(intro, text=f"{role}  •  {class_name}  •  {team}",
                 bg="white", fg=COLORS["gray"], font=("Arial", 9)).pack(anchor="w")

        self.button(top, "💬 Chat", self.chat_center, 12, COLORS["cyan"]).pack(side="right", padx=6, pady=10)
        self.button(top, "🔐 Thông tin của tôi", self.account_info, 17, COLORS["blue"]).pack(side="right", padx=6, pady=10)
        if s.get("parent_email_login"):
            self.button(top, "🔑 Đổi mật khẩu", self.change_parent_password, 16, COLORS["pink"]).pack(side="right", padx=6, pady=10)
        self.button(top, "↩ Đăng xuất", self.show_login, 13, "#7f8c8d").pack(side="right", padx=6, pady=10)

        # Chỉ dữ liệu của chính học sinh/con.
        cards = tk.Frame(shell, bg=COLORS["bg"])
        cards.pack(fill="x", padx=18)
        for idx, (title, value, sub, color, icon) in enumerate([
            ("Điểm thưởng / kỷ luật", f"{total:+d}", "Tổng hiện tại", COLORS["purple"], "⭐"),
            ("Nhiệm vụ", len(tasks), "Được giao", COLORS["green"], "🧹"),
            ("Đã hoàn thành", sum(1 for r in tasks if r["status"] == "Đã hoàn thành"), "Nhiệm vụ", COLORS["blue"], "✅"),
            ("Họ tên con / học sinh", name, f"Lớp {class_name}", COLORS["cyan"], "👤"),
        ]):
            f = self.stat_card(cards, title, value, sub, color, icon)
            f.grid(row=0, column=idx, padx=5, pady=5, sticky="nsew")
        for c in range(4):
            cards.grid_columnconfigure(c, weight=1)

        body = tk.Frame(shell, bg=COLORS["bg"])
        body.pack(fill="both", expand=True, padx=18, pady=12)

        score_card = tk.Frame(body, bg="white", bd=1, relief="solid")
        score_card.pack(side="left", fill="both", expand=True, padx=(0, 6))
        tk.Label(score_card, text="⭐ Điểm gần đây", bg="white",
                 fg=COLORS["navy"], font=("Arial", 14, "bold")).pack(anchor="w", padx=15, pady=12)
        tr1 = ttk.Treeview(score_card, columns=("criterion","points","note","created"),
                           show="headings", height=11)
        for c, h, w in [
            ("criterion","Tiêu chí",210),("points","Điểm",70),
            ("note","Ghi chú",250),("created","Thời gian",150)
        ]:
            tr1.heading(c, text=h); tr1.column(c, width=w)
        for r in scores:
            tr1.insert("", "end", values=(r["criterion"], f"{r['points']:+d}", r["note"] or "", r["created_at"]))
        tr1.pack(fill="both", expand=True, padx=10, pady=8)

        task_card = tk.Frame(body, bg="white", bd=1, relief="solid")
        task_card.pack(side="left", fill="both", expand=True, padx=(6, 0))
        tk.Label(task_card, text="🧹 Nhiệm vụ của tôi / con tôi", bg="white",
                 fg=COLORS["navy"], font=("Arial", 14, "bold")).pack(anchor="w", padx=15, pady=12)
        tr2 = ttk.Treeview(task_card, columns=("date","task","status","points"),
                           show="headings", height=11)
        for c, h, w in [
            ("date","Ngày",100),("task","Nhiệm vụ",250),
            ("status","Trạng thái",160),("points","Điểm",70)
        ]:
            tr2.heading(c, text=h); tr2.column(c, width=w)
        for r in tasks:
            tr2.insert("", "end", values=(r["task_date"], r["task"], r["status"], f"{r['points']:+d}"))
        tr2.pack(fill="both", expand=True, padx=10, pady=8)

        if s.get("officer_role"):
            box=tk.Frame(shell,bg="white",bd=1,relief="solid"); box.pack(fill="x",padx=18,pady=(0,10))
            tk.Label(box,text="🧑‍💼 QUYỀN BAN CÁN SỰ",bg="white",fg=COLORS["navy"],font=("Arial",13,"bold")).pack(anchor="w",padx=12,pady=8)
            scope=s.get("officer_scope","Không làm gì cả")
            if scope=="Không làm gì cả": tk.Label(box,text="Không có quyền tổ.",bg="white",fg=COLORS["gray"]).pack(anchor="w",padx=12,pady=5)
            else:
                self.button(box,"⭐ Xem điểm cộng của tổ",lambda:self.officer_team_view("scores",scope),24,COLORS["purple"]).pack(side="left",padx=8,pady=8)
                self.button(box,"🧹 Xem phân công / nhiệm vụ của tổ",lambda:self.officer_team_view("tasks",scope),30,COLORS["green"]).pack(side="left",padx=8,pady=8)
        if s.get("parent_email_login"):
            pbox=tk.Frame(shell,bg="white",bd=1,relief="solid")
            pbox.pack(fill="x",padx=18,pady=(0,10))
            tk.Label(pbox,text="👨‍👩‍👧 THÔNG TIN TỔ CỦA CON",bg="white",fg=COLORS["navy"],font=("Arial",13,"bold")).pack(anchor="w",padx=12,pady=8)
            self.button(pbox,"⭐ Thành tích / điểm cộng của tổ",lambda:self.parent_team_view("scores"),25,COLORS["purple"]).pack(side="left",padx=8,pady=8)
            self.button(pbox,"🧹 Phân công / nhiệm vụ của tổ",lambda:self.parent_team_view("tasks"),27,COLORS["green"]).pack(side="left",padx=8,pady=8)

        if s.get("transfer_notice"):
            messagebox.showinfo("Thông báo từ giáo viên",s.get("transfer_notice")); cx=connect(); cx.execute("UPDATE students SET transfer_notice='' WHERE id=?",(sid,)); cx.commit(); cx.close()

        footer = tk.Frame(shell, bg=COLORS["navy"])
        footer.pack(fill="x")
        tk.Label(footer, text=f"Giáo viên chủ nhiệm: {teacher}  •  Phụ huynh: {parent}",
                 bg=COLORS["navy"], fg="white", font=("Arial", 9)).pack(side="left", padx=16, pady=8)
        tk.Label(footer, text="🔒 Chỉ hiển thị dữ liệu của tài khoản/con bạn",
                 bg=COLORS["navy"], fg="white", font=("Arial", 9)).pack(side="right", padx=16, pady=8)

    def officer_team_view(self,kind,scope):
        s=self.current_student or {}; self.clear(); self.header("⭐ ĐIỂM CỘNG TỔ" if kind=="scores" else "🧹 PHÂN CÔNG / NHIỆM VỤ TỔ","Chỉ xem theo quyền giáo viên cấp")
        con=connect(); cls=s.get("class_name",""); team=s.get("team","")
        if scope=="Tất cả các tổ":
            where="st.class_name=?"; args=(cls,)
        else:
            where="st.class_name=? AND st.team=?"; args=(cls,team)
        if kind=="scores": rows=con.execute(f"SELECT st.name,st.team,sc.criterion,sc.points,sc.note,sc.created_at FROM scores sc JOIN students st ON st.id=sc.student_id WHERE {where} ORDER BY st.team,st.name,sc.id DESC",args).fetchall(); tr=self.tree(("name","team","criterion","points","note","created"),("Học sinh","Tổ","Tiêu chí","Điểm","Ghi chú","Thời gian"),[190,80,220,70,320,160]); [tr.insert("","end",values=(r["name"],r["team"],r["criterion"],f"{r['points']:+d}",r["note"] or "",r["created_at"])) for r in rows]
        else: rows=con.execute(f"SELECT st.name,st.team,t.task_date,t.task,t.status,t.points,t.note FROM tasks t JOIN students st ON st.id=t.student_id WHERE {where} ORDER BY st.team,st.name,t.id DESC",args).fetchall(); tr=self.tree(("name","team","date","task","status","points","note"),("Học sinh","Tổ","Ngày","Nhiệm vụ","Trạng thái","Điểm","Ghi chú"),[170,70,100,320,150,70,260]); [tr.insert("","end",values=(r["name"],r["team"],r["task_date"],r["task"],r["status"],f"{r['points']:+d}",r["note"] or "")) for r in rows]
        con.close(); self.button(self,"Quay lại tài khoản học sinh",self.student_home,24,"#7f8c8d").pack(pady=8)

    # -------------------- V9: CHAT --------------------
    def _chat_identity(self):
        """Trả về sender_type, student_id, sender_name cho tài khoản hiện tại."""
        s = self.current_student or {}
        if s.get("parent_email_login"):
            return "parent", s.get("student_id", s.get("id")), s.get("parent_name", "Phụ huynh")
        return ("student", s.get("id"), s.get("name", "Học sinh"))

    def _chat_liker_key(self):
        if self.current_student:
            typ, sid, _ = self._chat_identity()
            return f"{typ}:{sid}"
        return "teacher:1"

    def _chat_send_allowed(self, conv):
        """Quyền gửi chat:
        - Giáo viên: được gửi vào mọi nhóm lớp và nhắn riêng mọi HS/PH.
        - Học sinh/PH: không được gửi vào nhóm; chỉ được nhắn riêng với giáo viên.
        """
        if not conv:
            return False
        if self.current_student:
            if conv.get("type") == "group":
                # Không cho HS/PH gửi hoặc truy cập nhóm của lớp khác.
                return False
            sid = conv.get("student_id")
            own_sid = self.current_student.get("student_id", self.current_student.get("id"))
            own_type = "parent" if self.current_student.get("parent_email_login") else "student"
            return conv.get("type") == "private" and sid == own_sid and conv.get("peer_type") == own_type
        # Tài khoản giáo viên
        return conv.get("type") in ("group", "private")

    def _chat_group_read_only(self):
        return bool(self.current_student) and bool(self.current_chat) and self.current_chat.get("type") == "group"

    def _chat_group_allowed_for_current_user(self, class_name):
        """Học sinh/phụ huynh chỉ được xem đúng nhóm của lớp mình đã đăng ký."""
        if not self.current_student:
            return True
        own_class = str(self.current_student.get("class_name", "")).strip()
        return own_class != "" and str(class_name or "").strip() == own_class

    def _chat_load_contacts(self, search_text=""):
        con = connect()
        contacts = []
        if self.current_student:
            s = self.current_student
            cls = s.get("class_name", "")
            gr=con.execute("SELECT group_name FROM classes WHERE class_name=?",(cls,)).fetchone(); gn=(gr["group_name"] if gr and gr["group_name"] else f"Nhóm lớp {cls}")
            contacts.append({"type":"group","class_name":cls,"group_avatar_path":(gr["group_avatar_path"] if gr and "group_avatar_path" in gr.keys() else ""),"label":f"👥 {gn}","sub":"Giáo viên thông báo - chỉ xem trong nhóm"})
            contacts.append({"type":"private","peer_type":"parent" if s.get("parent_email_login") else "student", "student_id":s.get("student_id",s.get("id")), "label":"👩‍🏫 Giáo viên chủ nhiệm", "sub":s.get("homeroom_teacher", "")})
        else:
            classes = [r["class_name"] for r in con.execute("SELECT class_name FROM classes ORDER BY class_name").fetchall()]
            extra_classes = [r["class_name"] for r in con.execute("SELECT DISTINCT class_name FROM students WHERE class_name<>'' ORDER BY class_name").fetchall()]
            classes = sorted(set(classes + extra_classes))
            for cls in classes:
                gr=con.execute("SELECT group_name FROM classes WHERE class_name=?",(cls,)).fetchone(); gn=(gr["group_name"] if gr and gr["group_name"] else f"Nhóm lớp {cls}")
                contacts.append({"type":"group","class_name":cls,"group_avatar_path":(gr["group_avatar_path"] if gr and "group_avatar_path" in gr.keys() else ""),"label":f"👥 {gn}","sub":"Giáo viên gửi thông báo cho cả lớp"})
            students = con.execute("SELECT id,name,class_name,team FROM students WHERE status IN ('approved','verified') ORDER BY class_name,team,name").fetchall()
            for r in students:
                contacts.append({"type":"private","peer_type":"student","student_id":r["id"],"label":f"🎓 {r['name']}","sub":f"Học sinh • {r['class_name']} • {r['team']}"})
                contacts.append({"type":"private","peer_type":"parent","student_id":r["id"],"label":f"👨‍👩‍👧 {r['parent_name']}","sub":f"Phụ huynh của {r['name']} • {r['class_name']}"})
        con.close()
        q=(search_text or "").strip().casefold()
        if q:
            contacts=[c for c in contacts if q in c["label"].casefold() or q in c["sub"].casefold()]
        return contacts

    def chat_center(self):
        self.clear()
        self.configure(bg=COLORS["bg"])
        shell=tk.Frame(self,bg=COLORS["bg"]); shell.pack(fill="both",expand=True)
        top=tk.Frame(shell,bg="white",bd=1,relief="solid"); top.pack(fill="x",padx=14,pady=(12,8))
        tk.Label(top,text="💬 TRUNG TÂM CHAT",bg="white",fg=COLORS["navy"],font=("Arial",20,"bold")).pack(side="left",padx=14,pady=10)
        if self.current_student:
            tk.Label(top,text="Chat riêng với giáo viên + xem nhóm lớp",bg="white",fg=COLORS["gray"],font=("Arial",9)).pack(side="left")
        else:
            tk.Label(top,text="Nhiều nhóm theo lớp • Chat riêng giáo viên ↔ HS/PH",bg="white",fg=COLORS["gray"],font=("Arial",9)).pack(side="left")
        self.button(top,"↩ Quay lại",self.student_home if self.current_student else self.teacher_dashboard,13,"#7f8c8d").pack(side="right",padx=8,pady=8)

        body=tk.Frame(shell,bg=COLORS["bg"]); body.pack(fill="both",expand=True,padx=14,pady=(0,10))
        left=tk.Frame(body,bg="white",bd=1,relief="solid",width=300); left.pack(side="left",fill="y",padx=(0,7)); left.pack_propagate(False)
        tk.Label(left,text="Tìm kiếm",bg="white",fg=COLORS["gray"],font=("Arial",9,"bold")).pack(anchor="w",padx=12,pady=(10,3))
        search=tk.Entry(left,font=("Arial",10)); search.pack(fill="x",padx=12,pady=(0,8))
        lbframe=tk.Frame(left,bg="white"); lbframe.pack(fill="both",expand=True,padx=8,pady=4)
        sb=tk.Scrollbar(lbframe,orient="vertical"); lb=tk.Listbox(lbframe,activestyle="none",font=("Arial",10),bg="#f8fbff",bd=0,highlightthickness=0,yscrollcommand=sb.set)
        sb.config(command=lb.yview); lb.pack(side="left",fill="both",expand=True); sb.pack(side="right",fill="y")
        right=tk.Frame(body,bg="white",bd=1,relief="solid"); right.pack(side="left",fill="both",expand=True)
        chat_head=tk.Frame(right,bg="#f6f9ff",height=58); chat_head.pack(fill="x"); chat_head.pack_propagate(False)
        avatar_holder=tk.Frame(chat_head,bg="#f6f9ff"); avatar_holder.pack(side="left",padx=10,pady=7)
        title_var=tk.StringVar(value="Chọn một cuộc trò chuyện")
        tk.Label(chat_head,textvariable=title_var,bg="#f6f9ff",fg=COLORS["navy"],font=("Arial",13,"bold")).pack(side="left")
        tk.Label(chat_head,text="",bg="#f6f9ff").pack(side="left",fill="x",expand=True)

        msg_wrap=tk.Frame(right,bg="#eef5ff"); msg_wrap.pack(fill="both",expand=True)
        canvas=tk.Canvas(msg_wrap,bg="#eef5ff",bd=0,highlightthickness=0)
        msg_scroll=tk.Scrollbar(msg_wrap,orient="vertical",command=canvas.yview); canvas.configure(yscrollcommand=msg_scroll.set)
        canvas.pack(side="left",fill="both",expand=True); msg_scroll.pack(side="right",fill="y")
        inner=tk.Frame(canvas,bg="#eef5ff")
        inner_id=canvas.create_window((0,0),window=inner,anchor="nw")
        inner.bind("<Configure>",lambda e:canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>",lambda e:canvas.itemconfigure(inner_id,width=e.width))

        compose=tk.Frame(right,bg="white",bd=1,relief="solid"); compose.pack(fill="x")
        entry=tk.Text(compose,height=4,wrap="word",font=("Arial",10)); entry.pack(side="left",fill="both",expand=True,padx=8,pady=8)
        actions=tk.Frame(compose,bg="white",width=390); actions.pack(side="right",fill="y",padx=8,pady=8); actions.pack_propagate(False)
        attach_path=[""]

        send_btn=[None]

        def set_contact(idx):
            contacts=current_contacts[0]
            if idx<0 or idx>=len(contacts): return
            self.current_chat=contacts[idx]
            for w in avatar_holder.winfo_children(): w.destroy()
            if self.current_chat.get("type") == "group":
                gp=self.current_chat.get("group_avatar_path", "")
                if gp and os.path.exists(gp) and PIL_OK:
                    try:
                        im=Image.open(gp).convert("RGBA")
                        im.thumbnail((42,42))
                        ph=ImageTk.PhotoImage(im)
                        lab=tk.Label(avatar_holder,image=ph,bg="#f6f9ff")
                        lab.image=ph; lab.pack()
                    except Exception:
                        self.avatar_image(avatar_holder,42,"group:"+str(self.current_chat.get("class_name",""))).pack()
                else:
                    self.avatar_image(avatar_holder,42,"group:"+str(self.current_chat.get("class_name",""))).pack()
            else:
                seed=f"{self.current_chat.get('type')}:{self.current_chat.get('student_id',self.current_chat.get('class_name',''))}:{self.current_chat.get('peer_type','')}"
                self.avatar_image(avatar_holder,42,seed).pack()
            title_var.set(self.current_chat.get("label","Chat"))
            # Nhóm lớp là khu vực chỉ đọc đối với HS/PH.
            readonly = self._chat_group_read_only()
            try:
                entry.configure(state=("disabled" if readonly else "normal"))
            except Exception:
                pass
            if send_btn[0] is not None:
                send_btn[0].configure(state=("disabled" if readonly else "normal"))
            render_messages()

        current_contacts=[[]]
        def refresh_contacts(*_):
            current_contacts[0]=self._chat_load_contacts(search.get())
            lb.delete(0,"end")
            for c in current_contacts[0]: lb.insert("end",c["label"]+"\n  "+c["sub"])
            if current_contacts[0]:
                lb.selection_set(0); set_contact(0)
            else:
                self.current_chat=None; title_var.set("Không có cuộc trò chuyện phù hợp")
                for w in inner.winfo_children(): w.destroy()
        lb.bind("<<ListboxSelect>>",lambda e:set_contact(lb.curselection()[0]) if lb.curselection() else None)
        search.bind("<KeyRelease>",refresh_contacts)

        def render_messages():
            for w in inner.winfo_children(): w.destroy()
            conv=self.current_chat
            if not conv: return
            con=connect()
            if conv["type"]=="group":
                # Bảo mật: HS/PH chỉ được đọc nhóm đúng lớp của tài khoản hiện tại.
                if not self._chat_group_allowed_for_current_user(conv.get("class_name")):
                    con.close()
                    return
                rows=con.execute("SELECT * FROM chat_messages WHERE chat_type='group' AND class_name=? ORDER BY id",(conv["class_name"],)).fetchall()
            else:
                sid=conv["student_id"]; ptype=conv.get("peer_type","")
                rows=con.execute("SELECT * FROM chat_messages WHERE chat_type='private' AND peer_student_id=? AND peer_type=? ORDER BY id",(sid,ptype)).fetchall()
            con.close()
            for r in rows:
                mine=(r["sender_type"]=="teacher" and not self.current_student) or (self.current_student and r["sender_student_id"]==self.current_student.get("student_id",self.current_student.get("id")) and r["sender_type"] in ("student","parent"))
                row=tk.Frame(inner,bg="#eef5ff"); row.pack(fill="x",padx=10,pady=4)
                side=tk.RIGHT if mine else tk.LEFT
                bubble=tk.Frame(row,bg="#d9e9ff" if mine else "white",bd=1,relief="solid")
                bubble.pack(side=side,padx=6,anchor="e" if mine else "w")
                ah=tk.Frame(bubble,bg=bubble.cget("bg")); ah.pack(fill="x",padx=8,pady=(6,2))
                self.avatar_image(ah,30,f"{r['sender_type']}:{r['sender_student_id'] or 1}:{r['sender_name']}").pack(side="left")
                tk.Label(ah,text=r["sender_name"],bg=bubble.cget("bg"),fg=COLORS["navy"],font=("Arial",9,"bold")).pack(side="left",padx=7)
                tk.Label(ah,text=r["created_at"],bg=bubble.cget("bg"),fg=COLORS["gray"],font=("Arial",8)).pack(side="left")
                if r["message"]:
                    tk.Label(bubble,text=r["message"],bg=bubble.cget("bg"),fg=COLORS["dark"],justify="left",wraplength=540,font=("Arial",10)).pack(anchor="w",padx=10,pady=5)
                if r["attachment_path"]:
                    af=tk.Frame(bubble,bg=bubble.cget("bg")); af.pack(fill="x",padx=10,pady=3)
                    tk.Label(af,text="📎 "+os.path.basename(r["attachment_path"]),bg=bubble.cget("bg"),fg=COLORS["blue"],font=("Arial",9,"underline")).pack(side="left")
                    def open_attachment(path=r["attachment_path"]):
                        try:
                            if os.path.exists(path): os.startfile(path)
                            else: messagebox.showwarning("Tệp","Tệp không còn ở vị trí đã lưu.")
                        except Exception as ex: messagebox.showerror("Tệp",str(ex))
                    self.button(af,"Mở",open_attachment,6,COLORS["blue"]).pack(side="right")
                lc=connect(); liked=lc.execute("SELECT 1 FROM chat_likes WHERE message_id=? AND liker_key=?",(r["id"],self._chat_liker_key())).fetchone(); count=lc.execute("SELECT COUNT(*) n FROM chat_likes WHERE message_id=?",(r["id"],)).fetchone()["n"]; lc.close()
                def like_message(mid=r["id"]):
                    cx=connect()
                    already=cx.execute("SELECT 1 FROM chat_likes WHERE message_id=? AND liker_key=?",(mid,self._chat_liker_key())).fetchone()
                    if already: cx.execute("DELETE FROM chat_likes WHERE message_id=? AND liker_key=?",(mid,self._chat_liker_key()))
                    else: cx.execute("INSERT INTO chat_likes(message_id,liker_key,created_at) VALUES(?,?,?)",(mid,self._chat_liker_key(),now()))
                    cx.commit(); cx.close(); render_messages()
                # HS/PH ở nhóm lớp chỉ được xem, không được thả tim/tương tác.
                if not (conv["type"] == "group" and self.current_student):
                    self.button(bubble,('❤️' if liked else '♡')+f' {count}',like_message,9,"#ee6ca7" if liked else "#a7b4c8").pack(anchor="w",padx=8,pady=(0,6))
            canvas.update_idletasks(); canvas.yview_moveto(1.0)

        def choose_file():
            if self.current_student: return
            path=filedialog.askopenfilename(title="Chọn tệp gửi trong chat")
            if path:
                attach_path[0]=path; file_label.config(text="📎 "+os.path.basename(path))

        def send_message():
            conv=self.current_chat
            if not conv: return
            if not self._chat_send_allowed(conv):
                if conv.get("type") == "group":
                    messagebox.showwarning("Nhóm lớp","Nhóm lớp chỉ để học sinh/phụ huynh xem. Chỉ giáo viên được gửi tin nhắn.")
                else:
                    messagebox.showwarning("Chat riêng","Học sinh/phụ huynh chỉ được nhắn tin riêng với giáo viên.")
                return
            text=entry.get("1.0","end").strip()
            if not text and not attach_path[0]: return
            if self.current_student:
                stype,sid,sname=self._chat_identity()
                # Chặn tuyệt đối việc gửi private sang tài khoản HS/PH khác.
                if conv.get("type") != "private" or conv.get("student_id") != sid or conv.get("peer_type") != stype:
                    messagebox.showwarning("Chat riêng","Bạn chỉ có thể nhắn tin riêng với giáo viên.")
                    return
            else:
                stype,sid,sname="teacher",None,TEACHER_NAME
                if conv.get("type") == "private":
                    target_id=conv.get("student_id")
                    target_type=conv.get("peer_type")
                    con_chk=connect()
                    exists=con_chk.execute("SELECT 1 FROM students WHERE id=? AND status IN ('approved','verified')",(target_id,)).fetchone()
                    con_chk.close()
                    if not exists or target_type not in ("student","parent"):
                        messagebox.showerror("Chat riêng","Tài khoản người nhận không hợp lệ.")
                        return
            con=connect()
            con.execute("INSERT INTO chat_messages(chat_type,class_name,peer_student_id,peer_type,sender_type,sender_student_id,sender_name,message,attachment_path,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(
                conv["type"],conv.get("class_name", ""),conv.get("student_id"),conv.get("peer_type", ""),stype,sid,sname,text,attach_path[0],now()))
            con.commit(); con.close(); entry.configure(state="normal"); entry.delete("1.0","end"); attach_path[0]=""; file_label.config(text=""); render_messages()

        file_label=tk.Label(actions,text="",bg="white",fg=COLORS["gray"],font=("Arial",8),wraplength=300)
        file_label.grid(row=0,column=0,columnspan=2,sticky="ew",padx=2,pady=(0,3))
        actions.grid_columnconfigure(0,weight=1,minsize=170)
        actions.grid_columnconfigure(1,weight=1,minsize=170)
        actions.grid_rowconfigure(1,weight=1)
        actions.grid_rowconfigure(2,weight=1)
        actions.grid_rowconfigure(3,weight=1)
        if not self.current_student:
            self.button(actions,"📎 Gửi tệp",choose_file,1,COLORS["orange"]).grid(row=1,column=0,sticky="nsew",padx=4,pady=4,ipady=3)
            self.button(actions,"💬 Nhắn riêng",lambda:self.chat_private_picker(),1,COLORS["purple"]).grid(row=1,column=1,sticky="nsew",padx=4,pady=4,ipady=3)
            self.button(actions,"⚡ Tin nhắn nhanh",lambda:self.chat_quick_picker(entry),1,COLORS["purple"]).grid(row=2,column=0,sticky="nsew",padx=4,pady=4,ipady=3)
            self.button(actions,"⏰ Nhắc hẹn",self.chat_reminder_dialog,1,COLORS["pink"]).grid(row=2,column=1,sticky="nsew",padx=4,pady=4,ipady=3)
        send_btn[0]=self.button(actions,"➤ Gửi",send_message,1,COLORS["blue"])
        send_btn[0].grid(row=3,column=0,columnspan=2,sticky="nsew",padx=4,pady=(5,3),ipady=4)

        refresh_contacts()
        # Nếu mở từ nút "Nhắn riêng", ưu tiên đúng cuộc trò chuyện đã chọn.
        preferred_chat=getattr(self,"_preferred_chat",None)
        if preferred_chat:
            try:
                contacts_now=current_contacts[0]
                idx=next(i for i,c in enumerate(contacts_now)
                         if c.get("type")==preferred_chat.get("type")
                         and c.get("student_id")==preferred_chat.get("student_id")
                         and c.get("peer_type")==preferred_chat.get("peer_type"))
                lb.selection_clear(0,"end"); lb.selection_set(idx); lb.see(idx); set_contact(idx)
            except Exception:
                pass
            self._preferred_chat=None
        if self.chat_refresh_job:
            try:self.after_cancel(self.chat_refresh_job)
            except Exception:pass
        def periodic():
            if self.winfo_exists() and self.current_chat:
                render_messages()
                self.chat_refresh_job=self.after(5000,periodic)
        self.chat_refresh_job=self.after(5000,periodic)

